INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1, 2, 'Unparalleled', 'adj', 'Vô song / Không gì sánh bằng', 'Studying abroad gives young people an unparalleled opportunity to learn new languages and experience different cultures.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (2, 2, 'Memorize', 'v', 'Ghi nhớ / Học thuộc lòng', 'Students should understand the main ideas instead of trying to memorize every single fact for their exams.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (3, 1, 'Adolescence', 'n', 'Tuổi thiếu niên / Thời kỳ vị thành niên', 'During adolescence, teenagers experience many emotional changes and try to become more independent from their parents.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (4, 1, 'Adulthood', 'n', 'Tuổi trưởng thành', 'Entering adulthood brings important responsibilities, such as managing personal finances and building an independent career.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (5, 1, 'Bond', 'n', 'Mối quan hệ gắn kết / Tình cảm gắn bó', 'Sharing meals together every evening helps family members build a strong emotional bond with one another.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (6, 1, 'Brotherhood', 'n', 'Tình anh em / Tình huynh đệ', 'Playing sports together helps young men develop a strong sense of brotherhood and teamwork.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (7, 1, 'Character', 'n', 'Tính cách / Phẩm chất', 'Voluntary work helps students build strong character and learn how to help other people in need.', 5);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (8, 1, 'Childhood', 'n', 'Thời thơ ấu / Tuổi thơ', 'A happy childhood full of outdoor activities can positively affect a person''s mental health later in life.', 6);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (9, 1, 'Conflict', 'n', 'Sự xung đột / Mâu thuẫn', 'Open communication is the best way to resolve conflict between parents and their teenage children.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (10, 1, 'Connection', 'n', 'Mối quan hệ / Sự kết nối', 'Social media helps people maintain a close connection with friends who live in different countries.', 8);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (11, 1, 'Fatherhood', 'n', 'Thiên chức làm cha / Cương vị làm cha', 'Modern fatherhood involves spending more quality time at home caring for and educating young children.', 9);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (12, 1, 'Friendship', 'n', 'Tình bạn', 'True friendship is based on mutual trust, honesty, and support during difficult moments in life.', 10);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (13, 1, 'Instinct', 'n', 'Bản năng', 'When danger appears suddenly, a person''s natural instinct is to protect themselves and their family.', 11);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (14, 1, 'Interaction', 'n', 'Sự tương tác', 'Regular face-to-face interaction with teachers helps students understand difficult lessons much faster and better.', 12);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (15, 1, 'Motherhood', 'n', 'Thiên chức làm mẹ / Tình mẫu tử', 'Balancing the demands of motherhood with a full-time career can be challenging for many modern women.', 13);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (16, 1, 'Nature', 'n', 'Bản chất / Thiên nhiên', 'Spending time in nature on weekends helps workers reduce stress after a busy week.', 14);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (17, 1, 'Parent', 'n', 'Cha mẹ / Phụ huynh', 'Every parent wants to provide their children with a safe environment and a good education.', 15);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (18, 1, 'Relation', 'n', 'Mối quan hệ / Mối liên hệ / Người thân', 'There is a direct relation between regular exercise and improved physical and mental well-being.', 16);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (19, 1, 'Relationship', 'n', 'Mối quan hệ', 'Maintaining a good relationship with colleagues makes the daily work environment much more pleasant and productive.', 17);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (20, 1, 'Relative', 'n', 'Họ hàng / Người thân', 'During traditional holidays, people often travel back to their hometowns to visit every close relative.', 18);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (21, 1, 'Resemblance', 'n', 'Sự giống nhau / Nét tương đồng', 'The young boy shares a striking resemblance to his father in both appearance and gentle smile.', 19);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (22, 1, 'Rivalry', 'n', 'Sự cạnh tranh / Sự ganh đua', 'Healthy rivalry between classmates can motivate everyone to study harder and achieve better academic results.', 20);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (23, 1, 'Sibling', 'n', 'Anh chị em ruột', 'Children who grow up with an older sibling often learn to share their toys and cooperate easily.', 21);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (24, 1, 'Teenager', 'n', 'Thanh thiếu niên (13-19 tuổi)', 'Every teenager needs guidance from both parents and teachers to make good decisions about their future.', 22);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (25, 1, 'Temperament', 'n', 'Tính khí / Tâm tính', 'Her calm temperament helps her deal with difficult customers without getting angry or stressed.', 23);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (26, 1, 'Ties', 'n', 'Mối quan hệ gắn bó / Sự ràng buộc', 'Family ties remain extremely strong in Asian cultures even when children move away from home.', 24);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (27, 1, 'Upbringing', 'n', 'Sự nuôi dưỡng / Sự giáo dục gia đình', 'A loving family upbringing teaches children how to show kindness and respect toward other people.', 25);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (28, 1, 'Active role', 'n', 'Vai trò tích cực / Vai trò chủ động', 'Parents should play an active role in helping their children develop healthy reading habits at home.', 26);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (29, 1, 'Extended family', 'n', 'Đại gia đình (nhiều thế hệ)', 'Living in an extended family allows grandparents to help take care of their young grandchildren.', 27);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (30, 1, 'Family gathering', 'n', 'Buổi sum họp gia đình', 'Our annual family gathering during the New Year holiday brings together relatives from different cities.', 28);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (31, 1, 'Immediate family', 'n', 'Gia đình trực hệ (cha mẹ và con cái)', 'He decided to celebrate his university graduation quietly with only his immediate family members.', 29);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (32, 1, 'Maternal instinct', 'n', 'Bản năng làm mẹ', 'Her strong maternal instinct made her protect the injured child without thinking about her own safety.', 30);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (33, 1, 'Sibling rivalry', 'n', 'Sự ganh đua giữa anh chị em', 'Parents can reduce sibling rivalry by treating each child fairly and praising their unique talents.', 31);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (34, 1, 'Stable upbringing', 'n', 'Sự nuôi dạy ổn định / Sự giáo dục vững chắc', 'Children who enjoy a stable upbringing are usually more confident and successful in their adult lives.', 32);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (35, 1, 'Striking resemblance', 'n', 'Sự giống nhau đáng kinh ngạc', 'The little girl bears a striking resemblance to her grandmother when she was at that young age.', 33);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (36, 1, 'Close', 'adj', 'Gần gũi / Thân thiết', 'She maintains a close relationship with her childhood friends even though they live in different countries.', 34);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (37, 1, 'Close-knit', 'adj', 'Gắn bó khăng khít / Khăng khít', 'They grew up in a close-knit community where neighbors always supported each other in difficult times.', 35);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (38, 1, 'Maternal', 'adj', '(Thuộc) người mẹ / Phía ngoại', 'His maternal grandparents lived in the countryside and taught him how to grow organic vegetables.', 36);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (39, 1, 'Parental', 'adj', '(Thuộc) cha mẹ / Phụ huynh', 'Children need consistent parental guidance to navigate the dangers of using the internet safely.', 37);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (40, 1, 'Rewarding', 'adj', 'Đáng giá / Bổ ích / Đem lại cảm giác thỏa mãn', 'Teaching young children can be demanding, but it is one of the most rewarding careers in society.', 38);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (41, 1, 'Stable', 'adj', 'Ổn định / Vững chắc', 'A stable job with a reliable monthly income allows young couples to buy their first home.', 39);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (42, 1, 'Accommodate', 'v', 'Cung cấp chỗ ở / Đáp ứng (nhu cầu)', 'The new school building was designed to accommodate up to five hundred students and teachers.', 40);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (43, 1, 'Adopt', 'v', 'Nhận nuôi / Áp dụng (chính sách, phương pháp)', 'Many modern cities are trying to adopt green policies to reduce air pollution and protect public health.', 41);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (44, 1, 'Break down', 'v', 'Bị hỏng / Đổ vỡ / Suy sụp', 'Without clear communication and mutual trust, even long-lasting relationships can easily break down over time.', 42);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (45, 1, 'Develop', 'v', 'Phát triển / Mở rộng', 'Reading books every day helps young children develop their language skills and creative thinking ability.', 43);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (46, 1, 'Endure', 'v', 'Chịu đựng / Tồn tại lâu dài', 'True friendships can endure through difficult times and long periods of physical separation.', 44);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (47, 1, 'Establish', 'v', 'Thành lập / Thiết lập / Tạo dựng', 'It is important for parents to establish clear household rules to teach their children good discipline.', 45);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (48, 1, 'Have sth in common', 'v', 'Có điểm chung / Có cùng sở thích', 'Close friends often have many interests in common, which helps them understand each other better.', 46);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (49, 1, 'Inherit', 'v', 'Thừa hưởng / Kế thừa', 'Many children inherit physical traits from their parents, such as eye color and hair texture.', 47);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (50, 1, 'Interact', 'v', 'Tương tác / Tiếp xúc', 'Team sports give teenagers great opportunities to interact with peers and develop social skills.', 48);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (51, 1, 'Nurture', 'v', 'Nuôi dưỡng / Bồi dưỡng / Chăm sóc', 'Parents and teachers must work together to nurture a child''s natural talents and curiosity.', 49);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (52, 1, 'Play a role', 'v', 'Đóng một vai trò / Góp phần', 'Teachers play a role in helping young students build confidence and strong moral values.', 50);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (53, 1, 'Relate (to)', 'v', 'Thấu hiểu / Đồng cảm / Có liên hệ với', 'Many teenagers find it hard to relate to their parents because of modern lifestyle differences.', 51);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (54, 2, 'Adolescent', 'n', 'Người vị thành niên / Thanh thiếu niên', 'An adolescent often experiences emotional stress when preparing for competitive university entrance examinations.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (55, 2, 'Behaviour', 'n', 'Hành vi / Cách cư xử', 'Parents should encourage good behaviour by praising their children whenever they complete their daily chores.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (56, 2, 'Childhood', 'n', 'Thời thơ ấu / Tuổi thơ', 'Spending quality time with family during childhood creates warm memories that last for a lifetime.', 5);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (57, 2, 'Concept', 'n', 'Khái niệm / Quan niệm', 'The teacher used real-life examples to explain the complex concept of renewable energy to students.', 6);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (58, 2, 'Consequence', 'n', 'Hậu quả / Kết quả', 'Losing personal focus at school is often a direct consequence of spending too much time gaming.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (59, 2, 'Gesture', 'n', 'Cử chỉ / Điệu bộ', 'Giving a warm handshake is a common polite gesture when meeting business partners for the first time.', 8);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (60, 2, 'Growth', 'n', 'Sự tăng trưởng / Sự phát triển', 'A balanced daily diet rich in vitamins is essential for the healthy physical growth of children.', 9);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (61, 2, 'Imagination', 'n', 'Trí tưởng tượng', 'Reading adventure stories encourages children to use their imagination and explore new creative ideas.', 10);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (62, 2, 'Infancy', 'n', 'Thời kỳ sơ sinh / Giai đoạn ấu thơ', 'Nutritious food and emotional warmth during infancy are vital for healthy brain development.', 11);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (63, 2, 'Infant', 'n', 'Trẻ sơ sinh', 'A mother can usually tell whether her infant is crying because of hunger or feeling sleepy.', 12);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (64, 2, 'Maturity', 'n', 'Sự trưởng thành / Sự chín chắn', 'Living alone in a foreign city helps university students develop greater emotional maturity and self-discipline.', 13);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (65, 2, 'Memory', 'n', 'Trí nhớ / Ký ức', 'Regular physical exercise and healthy nutrition help elderly people maintain a sharp memory.', 14);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (66, 2, 'Milestone', 'n', 'Cột mốc quan trọng / Bước ngoặt', 'Graduating from university is a major milestone that marks the beginning of an independent professional life.', 15);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (67, 2, 'Mind', 'n', 'Tâm trí / Trí óc', 'Listening to relaxing classical music helps quiet the mind and improves concentration while studying.', 16);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (68, 2, 'Peers', 'n', 'Bạn đồng trang lứa / Bạn cùng tuổi', 'Teenagers often feel strong pressure from their peers to follow current fashion trends and lifestyles.', 17);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (69, 2, 'Period', 'n', 'Thời kỳ / Giai đoạn', 'Adolescence is a critical period when young people form their identities and choose their future paths.', 18);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (70, 2, 'Phase', 'n', 'Giai đoạn / Thời kỳ', 'The first phase of the environmental project will focus on cleaning local rivers and planting trees.', 19);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (71, 2, 'Rate', 'n', 'Tốc độ / Tỷ lệ', 'Children learn new vocabulary words at an impressive rate when their parents read books with them.', 20);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (72, 2, 'Reminder', 'n', 'Lời nhắc nhở / Vật nhắc nhớ', 'She placed a sticky note on her study desk as a visual reminder to finish her homework.', 21);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (73, 2, 'Social skills', 'n', 'Kỹ năng xã hội / Kỹ năng giao tiếp xã hội', 'Joining school clubs allows young students to develop effective social skills and make lifelong friends.', 22);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (74, 2, 'Stage', 'n', 'Giai đoạn / Thời kỳ', 'Learning to share toys with others is a crucial stage in early childhood social development.', 23);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (75, 2, 'Toddler', 'n', 'Trẻ mới biết đi (1-3 tuổi)', 'A toddler requires constant adult attention because they are naturally curious about everything around them.', 24);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (76, 2, 'Transition', 'n', 'Sự chuyển tiếp / Quá trình chuyển đổi', 'The transition from high school to university life can be overwhelming for many young students.', 25);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (77, 2, 'Abstract', 'adj', 'Trừu tượng', 'Young children find it much easier to understand concrete examples rather than purely abstract mathematical concepts.', 26);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (78, 2, 'Clumsy', 'adj', 'Vụng về / Hậu đậu', 'He felt clumsy when he accidentally dropped his coffee cup during his first job interview.', 27);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (79, 2, 'Fond', 'adj', 'Yêu thương / Đầy yêu thích / Thân thương', 'Most adults still cherish fond memories of spending carefree summer holidays in their rural hometowns.', 28);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (80, 2, 'Fully-grown', 'adj', 'Trưởng thành hoàn toàn / Phát triển đầy đủ', 'When a domestic cat becomes fully-grown, it requires a balanced diet to maintain a healthy weight.', 29);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (81, 2, 'Immature', 'adj', 'Chưa chín chắn / Non nớt', 'Blaming others for personal mistakes is an immature habit that prevents individuals from improving themselves.', 30);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (82, 2, 'Independent', 'adj', 'Tự lập / Độc lập', 'Living away from home teaches university students how to cook, clean, and become truly independent.', 31);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (83, 2, 'Irresponsible', 'adj', 'Vô trách nhiệm / Thiếu trách nhiệm', 'Driving a motor vehicle after drinking alcohol is an irresponsible action that endangers everyone on the road.', 32);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (84, 2, 'Mature', 'adj', 'Chín chắn / Trưởng thành', 'She demonstrated a mature attitude by listening calmly to constructive feedback from her school manager.', 33);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (85, 2, 'Patient', 'adj', 'Kiên nhẫn / Nhẫn nại', 'Primary school teachers must remain patient when helping young children learn basic reading and writing.', 34);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (86, 2, 'Rebellious', 'adj', 'Nổi loạn / Ương bướng', 'He went through a rebellious phase during high school, often questioning school rules and parental authority.', 35);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (87, 2, 'Significant', 'adj', 'Đáng kể / Quan trọng', 'Eating a nutritious breakfast provides a significant boost to energy levels and concentration during morning classes.', 36);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (88, 2, 'Tolerant', 'adj', 'Khoan dung / Có tính dung thứ', 'Living in a global city encourages citizens to be more tolerant of different cultures and perspectives.', 37);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (89, 2, 'Acquire', 'v', 'Tiếp thu / Đạt được', 'Young children acquire language naturally by listening to their parents talk and reading stories daily.', 38);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (90, 2, 'Develop', 'v', 'Phát triển / Rèn luyện', 'Participating in volunteer projects helps teenagers develop empathy and practical teamwork skills.', 39);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (91, 2, 'Gesture', 'v', 'Ra hiệu / Làm cử chỉ', 'Tourists often gesture with their hands when trying to communicate with locals in foreign countries.', 40);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (92, 2, 'Grow', 'v', 'Lớn lên / Phát triển', 'Healthy plants grow quickly when they receive plenty of sunlight, fresh water, and fertile soil.', 41);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (93, 2, 'Imitate', 'v', 'Bắt chước / Bắt chước theo', 'Young children naturally imitate the speech patterns and daily habits of their parents at home.', 42);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (94, 2, 'Look back', 'v', 'Nhìn lại / Nhớ lại', 'Older people often look back on their youthful adventures with deep fondness and gentle laughter.', 43);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (95, 2, 'Master', 'v', 'Làm chủ / Nắm vững (kỹ năng)', 'It takes regular practice and genuine patience to master a difficult foreign language like Japanese.', 44);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (96, 2, 'Mature', 'v', 'Trưởng thành / Trở nên chín chắn', 'Teenagers gradually mature as they face everyday responsibilities and make important decisions about their future.', 45);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (97, 2, 'Remember', 'v', 'Ghi nhớ / Nhớ', 'Students should remember to bring their identity cards and admission tickets to the examination room.', 46);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (98, 2, 'Remind', 'v', 'Nhắc nhở / Gợi nhớ', 'Smartphones can remind busy professionals about upcoming appointments and important daily deadlines.', 47);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (99, 2, 'Reminisce', 'v', 'Hồi tưởng / Nhớ lại quá khứ', 'My grandparents often reminisce about their youth when our whole family gathers for dinner.', 48);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (100, 2, 'Throw a tantrum', 'v', 'Nổi cơn tam bành / Ăn vạ / Nổi giận đùng đùng', 'Young children often throw a tantrum when they do not get the toys they want.', 49);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (101, 2, 'Visualise', 'v', 'Hình dung / Mường tượng trong tâm trí', 'Teachers often encourage students to visualise the story before they start writing their essays.', 50);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (102, 2, 'Typically', 'v', 'Thông thường / Điển hình', 'Students typically spend several hours each day reviewing their lessons and preparing for exams.', 51);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (103, 2, 'Bear in mind', 'phrase', 'Ghi nhớ / Hãy nhớ rằng', 'You should bear in mind that learning a foreign language requires regular practice and patience.', 52);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (104, 2, 'Broaden the mind', 'phrase', 'Mở rộng tầm hiểu biết / Mở mang đầu óc', 'Traveling to different countries can help young people broaden the mind and understand new cultures.', 53);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (105, 2, 'Have something in mind', 'phrase', 'Có ý định / Có ý tưởng trong đầu', 'Do you have something in mind for the weekend, or should we go to the cinema?', 54);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (106, 2, 'Have something on your mind', 'phrase', 'Có điều đang bận tâm / Lo lắng về điều gì', 'You look quiet today; do you have something on your mind about your final examination?', 55);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (107, 2, 'It slipped my mind', 'phrase', 'Tôi quên khuấy mất / Vô tình quên mất', 'I was planning to buy some fresh milk after work, but it completely slipped my mind.', 56);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (108, 2, 'Keep an open mind', 'phrase', 'Giữ tư duy cởi mở / Sẵn sàng tiếp thu ý kiến mới', 'It is important to keep an open mind when you listen to opinions that differ from yours.', 57);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (109, 2, 'My mind went blank', 'phrase', 'Đầu óc tôi trống rỗng / Quên sạch không nghĩ ra được gì', 'When the teacher asked me a difficult question in class, my mind went completely blank.', 58);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (110, 2, 'Put your mind at ease', 'phrase', 'Làm cho bạn an tâm / Giải tỏa lo lắng', 'The doctor explained the test results clearly to put her mind at ease before the surgery.', 59);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (111, 3, 'Allergy', 'n', 'Dị ứng / Bệnh dị ứng', 'He developed a severe food allergy after eating seafood during his holiday at the beach.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (112, 3, 'Anxiety', 'n', 'Sự lo âu / Cảm giác lo lắng', 'Many high school students experience anxiety before taking important examinations like the IELTS test.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (113, 3, 'Appetite', 'n', 'Sự thèm ăn / Khẩu vị', 'Doing regular physical exercise in the morning can help improve your appetite and mood.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (114, 3, 'Artery', 'n', 'Động mạch', 'Eating too much fatty food can block a main artery and lead to serious heart problems.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (115, 3, 'Asset', 'n', 'Tài sản quý giá / Thế mạnh / Lợi thế', 'Good physical health is a valuable asset that helps people work efficiently and enjoy life.', 5);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (116, 3, 'Benefit', 'n', 'Lợi ích / Thuận lợi', 'One major benefit of walking every day is that it strengthens your heart and bones.', 6);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (117, 3, 'Cravings', 'n', 'Cơn thèm đồ ăn / Cảm giác thèm thuồng', 'Drinking plenty of water throughout the day can help you control cravings for sweet snacks.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (118, 3, 'Depression', 'n', 'Bệnh trầm cảm / Tình trạng trầm cảm', 'Physical activity and outdoor hobbies are effective ways to reduce stress and prevent depression.', 8);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (119, 3, 'Diagnosis', 'n', 'Sự chẩn đoán / Kết quả chẩn đoán bệnh', 'An early diagnosis of the disease gives patients a much higher chance of full recovery.', 9);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (120, 3, 'Diet', 'n', 'Chế độ ăn uống / Chế độ ăn kiêng', 'A balanced diet with plenty of green vegetables and fresh fruits is essential for good health.', 10);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (121, 3, 'Dietician', 'n', 'Chuyên gia dinh dưỡng', 'She decided to consult a professional dietician to build a healthier meal plan for weight loss.', 11);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (122, 3, 'Disease', 'n', 'Bệnh tật / Căn bệnh', 'Frequent hand washing is a simple way to prevent the spread of infectious disease.', 12);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (123, 3, '(eating) disorder', 'n', 'Rối loạn ăn uống', 'Social media pressure about body image can cause teenagers to develop an eating disorder.', 13);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (124, 3, 'Exercise', 'n', 'Sự tập thể dục / Bài tập thể dục', 'Doctors advise adults to do at least thirty minutes of moderate exercise every single day.', 14);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (125, 3, 'Factor', 'n', 'Yếu tố / Nhân tố', 'Poor nutrition is a leading factor that causes many chronic illnesses among middle-aged people.', 15);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (126, 3, 'Fast food', 'n', 'Thức ăn nhanh / Đồ ăn nhanh', 'Many busy parents rely on fast food for dinner because they lack time to cook.', 16);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (127, 3, 'Fat', 'n', 'Chất béo / Mỡ', 'Eating too much saturated fat can raise cholesterol levels and harm your cardiovascular system.', 17);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (128, 3, 'Harm', 'n', 'Sự tổn hại / Tác hại', 'Staying up late every night can cause serious harm to your immune system and memory.', 18);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (129, 3, 'Health', 'n', 'Sức khỏe', 'Regular exercise and adequate sleep are vital habits for maintaining good mental and physical health.', 19);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (130, 3, 'Heart attack', 'n', 'Cơn đau tim / Cơn nhồi máu cơ tim', 'He stopped smoking and changed his diet immediately after surviving a mild heart attack.', 20);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (131, 3, 'Infection', 'n', 'Sự nhiễm trùng / Tình trạng nhiễm khuẩn', 'You should clean the wound thoroughly to prevent a bacterial infection from getting worse.', 21);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (132, 3, 'Ingredients', 'n', 'Nguyên liệu / Thành phần món ăn', 'Cooking at home allows you to choose fresh ingredients and avoid harmful chemical additives.', 22);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (133, 3, 'Insomnia', 'n', 'Chứng mất ngủ / Bệnh khó ngủ', 'Drinking coffee late in the evening is one of the most common causes of insomnia.', 23);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (134, 3, 'Intake', 'n', 'Lượng nạp vào / Lượng tiêu thụ', 'Nutrition experts recommend that adults should reduce their daily intake of salt and sugar.', 24);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (135, 3, 'Junk food', 'n', 'Đồ ăn vặt không lành mạnh / Thức ăn rác', 'Schools should ban junk food in their cafeterias to encourage students to eat healthy meals.', 25);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (136, 3, 'Muscle', 'n', 'Cơ bắp / Bắp thịt', 'Lifting weights regularly helps to build muscle strength and improve overall body posture.', 26);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (137, 3, 'Nutrient', 'n', 'Chất dinh dưỡng', 'Green vegetables provide every essential nutrient that our body needs to stay completely healthy.', 27);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (138, 3, 'Nutrition', 'n', 'Dinh dưỡng / Chế độ dinh dưỡng', 'Schools should educate young children about nutrition so that they can form healthy eating habits.', 28);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (139, 3, 'Obesity', 'n', 'Bệnh béo phì / Tình trạng béo phì', 'Childhood obesity has become a serious public health issue in many developed countries today.', 29);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (140, 3, 'Onset', 'n', 'Sự khởi phát / Thời điểm bắt đầu', 'Regular exercise can significantly delay the onset of many age-related health conditions.', 30);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (141, 3, 'Portion', 'n', 'Khẩu phần ăn / Phần chia', 'Eating a smaller portion of rice at dinner helped him control his daily calorie intake.', 31);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (142, 3, 'Risk', 'n', 'Nguy cơ / Rủi ro', 'Smoking cigarettes and drinking too much alcohol greatly increase the risk of heart disease.', 32);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (143, 3, 'Serving', 'n', 'Khẩu phần ăn / Suất ăn', 'Health experts suggest eating at least one serving of fresh vegetables with every meal.', 33);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (144, 3, 'Stress', 'n', 'Sự căng thẳng / Áp lực tinh thần', 'Many working people listen to classical music to relieve stress after a long busy day.', 34);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (145, 3, 'Stroke', 'n', 'Cơn đột quỵ / Tai biến mạch máu não', 'High blood pressure is one of the main factors that can cause a dangerous stroke.', 35);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (146, 3, 'Treatment', 'n', 'Sự điều trị / Liệu trình chữa bệnh', 'Modern medical treatment has helped many patients recover quickly from severe physical injuries.', 36);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (147, 3, 'Therapy', 'n', 'Liệu pháp / Phương pháp trị liệu', 'He attended physical therapy twice a week to regain full movement in his injured leg.', 37);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (148, 3, 'Variety', 'n', 'Sự đa dạng / Nhiều loại phong phú', 'You should eat a wide variety of colorful fruits and vegetables to absorb different vitamins.', 38);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (149, 3, 'Weight', 'n', 'Cân nặng / Trọng lượng', 'She managed to lose excess weight by combining daily jogging with a balanced healthy diet.', 39);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (150, 3, 'Acute', 'adj', 'Cấp tính / Dữ dội / Rất nghiêm trọng', 'The patient was rushed to the local hospital after experiencing acute pain in his chest.', 40);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (151, 3, 'Allergic', 'adj', 'Bị dị ứng / Có cơ địa dị ứng', 'My younger brother is allergic to seafood, so he always avoids eating prawns and crabs.', 41);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (152, 3, 'Alternate', 'adj', 'Luân phiên / Xen kẽ / Cách ngày', 'She attends fitness classes on alternate days to give her muscles sufficient time to rest.', 42);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (153, 3, 'Brisk', 'adj', 'Nhanh nhẹn / Nhanh và dứt khoát', 'Taking a thirty-minute brisk walk every morning helps stimulate blood circulation and burn fat.', 43);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (154, 3, 'Chronic', 'adj', 'Mãn tính / Kinh niên kéo dài', 'Patients suffering from chronic back pain often find gentle swimming very beneficial for recovery.', 44);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (155, 3, 'Harmful', 'adj', 'Có hại / Gây nguy hại', 'Smoking cigarettes and drinking excessive alcohol have extremely harmful effects on your internal organs.', 45);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (156, 3, 'Healthy', 'adj', 'Khỏe mạnh / Lành mạnh', 'Maintaining a healthy lifestyle through good food and regular exercise prevents many serious diseases.', 46);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (157, 3, 'Infectious', 'adj', 'Lây nhiễm / Truyền nhiễm', 'Flu is an infectious illness that spreads very quickly among children in crowded classrooms.', 47);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (158, 3, 'Moderate', 'adj', 'Vừa phải / Điều độ', 'Doing moderate exercise for twenty minutes each morning can improve your overall energy levels.', 48);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (159, 3, 'Obese', 'adj', 'Bị béo phì', 'People who are obese face a significantly higher risk of developing diabetes and heart problems.', 49);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (160, 3, 'Overweight', 'adj', 'Thừa cân / Quá cân', 'Many overweight children find it difficult to participate actively in physical sports at school.', 50);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (161, 3, 'Persistent', 'adj', 'Dai dẳng / Kiên trì / Kéo dài liên tục', 'If you suffer from a persistent cough for two weeks, you should see a doctor.', 51);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (162, 3, 'Regular', 'adj', 'Đều đặn / Thường xuyên', 'Doing regular exercise helps you maintain a healthy body and reduce stress after work.', 52);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (163, 3, 'Vital', 'adj', 'Thiết yếu / Vô cùng quan trọng', 'Drinking plenty of clean water every day plays a vital role in maintaining good health.', 53);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (164, 3, 'Avoid', 'v', 'Tránh xa / Tránh né', 'Doctors advise patients with heart conditions to avoid foods that contain high amounts of salt.', 54);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (165, 3, 'Counteract', 'v', 'Chống lại / Làm giảm bớt tác hại', 'Eating fresh green vegetables can help counteract the negative effects of stress on your body.', 55);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (166, 3, 'Curb', 'v', 'Kiềm chế / Kìm hãm / Ngăn chặn', 'The government has introduced new tax policies to curb the consumption of sugary drinks.', 56);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (167, 3, 'Cure', 'v', 'Chữa khỏi / Điều trị dứt điểm', 'Modern antibiotics can easily cure many bacterial infections that were once dangerous to humans.', 57);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (168, 3, 'Diminish', 'v', 'Giảm bớt / Suy giảm', 'Getting enough sleep at night will help diminish feelings of anxiety and fatigue during work.', 58);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (169, 3, 'Disrupt', 'v', 'Làm gián đoạn / Gây xáo trộn', 'Using smartphones late at night can severely disrupt your natural sleep cycle and cause insomnia.', 59);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (170, 3, 'Eliminate', 'v', 'Loại bỏ / Triệt tiêu hoàn toàn', 'To lose weight effectively, you should try to eliminate sugary snacks from your daily diet.', 60);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (171, 3, 'Maintain', 'v', 'Duy trì / Giữ gìn', 'It is important for older adults to maintain a regular exercise routine to stay active.', 61);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (172, 3, 'Overdo', 'v', 'Làm quá mức / Vận động quá sức', 'Beginners should not overdo their gym workouts because it can easily lead to serious injuries.', 62);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (173, 3, 'Overeat', 'v', 'Ăn quá nhiều / Ăn quá độ', 'People tend to overeat when they watch television because they do not notice feeling full.', 63);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (174, 3, 'Prevent', 'v', 'Ngăn chặn / Phòng ngừa', 'Washing your hands with soap before meals helps prevent the spread of harmful bacteria.', 64);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (175, 3, 'Recommend', 'v', 'Khuyên bảo / Đề xuất', 'Doctors often recommend eating fresh fruit instead of processed snacks to protect your overall health.', 65);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (176, 3, 'Recover', 'v', 'Hồi phục / Bình phục', 'It usually takes several weeks for patients to recover fully after having major surgery.', 66);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (177, 3, 'Reduce', 'v', 'Giảm bớt / Cắt giảm', 'Practicing yoga every morning can help reduce mental tension and improve your flexibility.', 67);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (178, 3, 'Skip', 'v', 'Bỏ qua / Bỏ bữa', 'You should never skip breakfast because it gives you vital energy for the entire morning.', 68);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (179, 3, 'Stimulate', 'v', 'Kích thích / Thúc đẩy', 'Reading books and solving puzzles can stimulate brain activity and enhance your memory as you age.', 69);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (180, 3, 'Trigger', 'v', 'Gây ra / Khơi mào / Kích hoạt', 'Eating certain foods or smelling strong chemicals can trigger a painful migraine headache.', 70);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (181, 4, 'Activity', 'n', 'Hoạt động', 'Outdoor activity like cycling in the park helps children develop strong muscles and healthy habits.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (182, 4, 'Aspect', 'n', 'Khía cạnh / Phương diện', 'Work-life balance is an important aspect of modern lifestyle that many young workers care about.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (183, 4, 'Attitude', 'n', 'Thái độ / Quan điểm sống', 'Maintaining a positive attitude toward challenges can help you overcome stress in your daily life.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (184, 4, '(achieve a) balance', 'n', 'Sự cân bằng / Đạt được sự cân bằng', 'It is difficult for working parents to achieve a balance between their careers and family life.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (185, 4, 'Competition', 'n', 'Cuộc thi / Sự cạnh tranh', 'Taking part in a friendly sports competition encourages teenagers to build teamwork and confidence.', 5);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (186, 4, 'Creativity', 'n', 'Sự sáng tạo / Óc sáng tạo', 'Art classes in primary schools provide a great way for children to develop their creativity.', 6);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (187, 4, 'Daily routine', 'n', 'Thói quen hằng ngày / Lịch trình hằng ngày', 'Having a stable daily routine helps students manage their study time much more effectively.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (188, 4, 'Desire', 'n', 'Khao khát / Mong muốn', 'Many young people share a strong desire to travel abroad and explore new cultures.', 8);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (189, 4, 'Disappointment', 'n', 'Sự thất vọng / Nỗi thất vọng', 'She could not hide her disappointment when she received lower exam scores than she expected.', 9);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (190, 4, 'Experience', 'n', 'Kinh nghiệm / Trải nghiệm', 'Volunteering in community projects is an enriching experience that teaches valuable social skills.', 10);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (191, 4, 'Fulfilment', 'n', 'Cảm giác viên mãn / Sự thỏa nguyện', 'Helping others in need brings a deep sense of personal fulfilment and happiness to volunteers.', 11);
