INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (194, 4, 'Insight', 'n', 'Cái nhìn sâu sắc / Sự hiểu biết sâu sắc', 'The guest speaker gave valuable insight into how modern technology is reshaping our daily lifestyles.', 14);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (195, 4, 'Leisure', 'n', 'Thời gian rảnh rỗi / Hoạt động thư giãn', 'Most busy professionals enjoy spending their leisure time with family or playing outdoor sports.', 15);
