INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (197, 4, 'Optimist', 'n', 'Người lạc quan', 'As an optimist, she always believes that hard work will lead to success in life.', 17);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (198, 4, 'Outlook', 'n', 'Quan điểm / Cách nhìn / Triển vọng', 'Travelling to different countries can help young people develop a positive outlook on life.', 18);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (199, 4, 'Opportunity', 'n', 'Cơ hội / Dịp tốt', 'Studying abroad provides students with a great opportunity to learn about new cultures.', 19);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (200, 4, 'Personality', 'n', 'Tính cách / Nhân cách', 'Parents play an important role in shaping the personality and behavior of their children.', 20);
