INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (204, 4, 'Realist', 'n', 'Người thực tế', 'He is a realist who accepts practical difficulties rather than dreaming about perfection.', 24);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (205, 4, 'Risk-taker', 'n', 'Người thích mạo hiểm / Người dám chấp nhận rủi ro', 'A successful entrepreneur is often a risk-taker who is not afraid of failure.', 25);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (206, 4, 'Self-expression', 'n', 'Sự tự thể hiện bản thân', 'Art and music give young people a creative way for emotional self-expression.', 26);
