INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (208, 4, 'Active', 'adj', 'Năng động / Tích cực', 'Children who lead an active lifestyle are generally healthier and more energetic.', 28);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (209, 4, 'Bored', 'adj', 'Buồn chán / Cảm thấy chán', 'Students often get bored when the lessons are too long and not interactive.', 29);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (210, 4, 'Confused', 'adj', 'Bối rối / Hoang mang', 'Fresh graduates often feel confused when choosing the right career path for themselves.', 30);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (211, 4, 'Dissatisfied', 'adj', 'Không hài lòng / Bất mãn', 'Many customers were dissatisfied with the slow customer service at the local bank.', 31);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (212, 4, 'Intense', 'adj', 'Mãnh liệt / Dữ dội / Cao độ', 'University students often experience intense pressure during their final examination period.', 32);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (213, 4, 'Materialistic', 'adj', 'Thực dụng / Coi trọng vật chất', 'Modern society has become more materialistic because people often judge success by wealth.', 33);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (214, 4, 'Negative', 'adj', 'Tiêu cực / Bi quan', 'Spending too much time on social media can have a negative impact on mental health.', 34);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (215, 4, 'Outdoor', 'adj', 'Ngoài trời', 'Schools should encourage outdoor activities to help children stay active and fit.', 35);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (216, 4, 'Positive', 'adj', 'Tích cực / Lạc quan', 'Regular exercise and a balanced diet bring many positive benefits to physical health.', 36);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (217, 4, 'Recreational', 'adj', 'Giải trí / Tiêu khiển', 'The city should build more recreational facilities like public parks and sports centers.', 37);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (218, 4, 'Successful', 'adj', 'Thành công', 'Hard work and dedication are essential qualities to become successful in your chosen career.', 38);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (219, 4, 'Achieve (a goal)', 'v', 'Đạt được (mục tiêu) / Hoàn thành', 'You need a clear plan and strong discipline to achieve a goal in your studies.', 39);
