INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (221, 4, 'Attract', 'v', 'Thu hút / Lôi cuốn', 'Big cities always attract young people because of abundant job opportunities and modern lifestyle.', 41);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (222, 4, 'Choose', 'v', 'Chọn / Lựa chọn', 'Many students choose to live in a dormitory to save accommodation costs.', 42);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (223, 4, 'Express', 'v', 'Bày tỏ / Thể hiện', 'It is important for children to learn how to express their feelings calmly and clearly.', 43);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (224, 4, 'Enjoy', 'v', 'Thưởng thức / Tận hưởng / Thích', 'Many young people enjoy spending their weekends doing outdoor activities with close friends.', 44);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (225, 4, 'Fulfil', 'v', 'Thực hiện / Hoàn thành / Làm thỏa mãn', 'He worked very hard to fulfil his dream of becoming a university lecturer.', 45);
