INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (227, 4, 'Motivate', 'v', 'Thúc đẩy / Động viên / Tạo động lực', 'Good teachers always motivate their students to explore new knowledge and think independently.', 47);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (228, 4, 'Participate', 'v', 'Tham gia', 'Students should actively participate in community services to gain valuable practical experience.', 48);
