INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (230, 4, 'Relax', 'v', 'Thư giãn / Nghỉ ngơi', 'Listening to soft music is a wonderful way to relax after a stressful working day.', 50);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (231, 4, 'Satisfy', 'v', 'Làm hài lòng / Thỏa mãn / Đáp ứng', 'The company improved its product quality to satisfy the increasing demands of modern customers.', 51);
