INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (258, 5, 'Exam', 'n', 'Kỳ thi / Bài thi', 'Students should review their study notes carefully before taking the final semester exam.', 7);
