INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (283, 5, 'Scope', 'n', 'Phạm vi / Quy mô', 'The scope of this research paper is limited to renewable energy use in developing countries.', 32);
