INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (287, 5, 'Task', 'n', 'Nhiệm vụ / Bài tập được giao', 'Completing this difficult writing task requires students to conduct extensive background research.', 36);
