INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (289, 5, 'Thesis', 'n', 'Luận văn / Luận án tốt nghiệp', 'She spent almost an entire year conducting field surveys to complete her master thesis.', 38);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (290, 5, 'Tutor', 'n', 'Gia sư / Giảng viên hướng dẫn', 'My private tutor helped me improve my English pronunciation and grammar significantly before the exam.', 39);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (291, 5, 'Topic', 'n', 'Chủ đề / Đề tài', 'Choosing an interesting topic makes writing an academic essay much more enjoyable and effective.', 40);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (292, 5, 'University', 'n', 'Trường đại học', 'Entering university gives young adults more independence and helps them prepare for future careers.', 41);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (293, 5, 'Academic', 'adj', 'Thuộc học thuật / Mang tính học thuật', 'Good academic performance in school can open doors to prestigious universities and attractive scholarships.', 42);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (294, 5, 'Eligible', 'adj', 'Đủ điều kiện / Đủ tư cách', 'Only students with high grade point averages are eligible to apply for this international scholarship.', 43);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (295, 5, 'Mixed', 'adj', 'Hỗn hợp / Đan xen / Cả nam lẫn nữ', 'Many students prefer to study in mixed schools because it prepares them for real life.', 44);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (296, 5, 'Postgraduate', 'adj', 'Sau đại học', 'She decided to apply for a postgraduate course in education to improve her career prospects.', 45);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (297, 5, 'Relevant', 'adj', 'Có liên quan / Thích hợp', 'University courses should provide relevant skills that help graduates find good jobs easily.', 46);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (298, 5, 'Senior', 'adj', 'Cấp cao / Lớn tuổi hơn / Lâu năm', 'First-year students often receive helpful advice from senior students about campus life.', 47);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (299, 5, 'Single-sex', 'adj', 'Đơn giới tính / Dành riêng cho nam hoặc nữ', 'Some parents choose single-sex schools because they believe students can concentrate better.', 48);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (300, 5, 'Studious', 'adj', 'Chăm học / Ham học', 'He is a studious person who spends most of his free time reading in the library.', 49);
