INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (302, 5, 'Adopt (an approach)', 'v', 'Áp dụng (một cách tiếp cận / một phương pháp)', 'Teachers should adopt a modern approach to help students learn English more effectively.', 51);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (303, 5, 'Analyse', 'v', 'Phân tích', 'Students need to analyse the survey results carefully before writing their final report.', 52);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (304, 5, 'Conduct', 'v', 'Tiến hành / Thực hiện', 'Scientists conduct research to discover new ways to protect the natural environment.', 53);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (305, 5, 'Concentrate', 'v', 'Tập trung', 'It is difficult for children to concentrate on studying when their room is noisy.', 54);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (306, 5, 'Consider', 'v', 'Cân nhắc / Xem xét', 'High school graduates should consider their personal interests before choosing a university major.', 55);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (307, 5, 'Find out', 'v', 'Tìm hiểu / Khám phá ra', 'Students can visit the university website to find out more about tuition fees.', 56);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (308, 5, 'Graduate', 'v', 'Tốt nghiệp', 'After they graduate from university, many young people want to travel abroad.', 57);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (309, 5, 'Learn (about)', 'v', 'Tìm hiểu về / Học về', 'History classes allow young students to learn about different cultures and traditions.', 58);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (310, 5, 'Organise', 'v', 'Tổ chức / Sắp xếp', 'The school will organise a sports event to encourage students to stay healthy.', 59);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (311, 5, 'Overcome', 'v', 'Vượt qua / Khắc phục', 'Practicing speaking every day helped him overcome his fear of making mistakes.', 60);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (312, 5, 'Review', 'v', 'Ôn tập / Xem lại / Đánh giá', 'You should review your notes every evening to prepare well for exams.', 61);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (313, 5, 'Revise', 'v', 'Ôn tập / Sửa đổi', 'Students often spend several weeks revising their lessons before the final examination.', 62);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (314, 5, 'Struggle', 'v', 'Gặp khó khăn / Vật lộn', 'Many international students struggle with the language barrier during their first semester.', 63);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (315, 5, 'Take (a course)', 'v', 'Tham gia (khóa học) / Học (một khóa)', 'I decided to take an online course to improve my digital skills.', 64);
