INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (317, 6, 'Accuracy', 'n', 'Độ chính xác / Sự chính xác', 'Language learners should focus on both accuracy and fluency when practicing speaking.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (318, 6, 'Communication', 'n', 'Giao tiếp / Sự liên lạc / Truyền thông', 'Good communication skills are essential for building positive relationships at work.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (319, 6, 'Concept', 'n', 'Khái niệm / Ý tưởng', 'The professor used simple examples to explain a difficult scientific concept to students.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (320, 6, 'Conjecture', 'n', 'Sự phỏng đoán / Sự ước đoán', 'Without clear evidence, the news report was based purely on conjecture.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (321, 6, 'Dialect', 'n', 'Phương ngữ / Tiếng địa phương', 'People from different regions of the country often speak with a distinct dialect.', 5);
