INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (323, 6, 'Gesture', 'n', 'Cử chỉ / Điệu bộ', 'A friendly gesture such as a smile can help break the ice when meeting new people.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (324, 6, 'Hesitation', 'n', 'Sự do dự / Sự ngập ngừng', 'Too much hesitation during the speaking test can lower your overall fluency score.', 8);
