INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (327, 6, 'Linguist', 'n', 'Nhà ngôn ngữ học', 'As a linguist, she studies how children acquire their first language naturally.', 11);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (328, 6, 'Linguistics', 'n', 'Ngôn ngữ học', 'He chose to study linguistics at university because he is fascinated by word origins.', 12);
