INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (338, 6, 'Spontaneous', 'adj', 'Tự phát / Tự nhiên / Ngẫu hứng', 'Her spontaneous response showed that she truly understood the question.', 22);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (339, 6, 'Clarify', 'v', 'Làm rõ / Giải thích rõ ràng', 'The teacher used simple examples to clarify the rules of the grammar lesson.', 23);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (340, 6, 'Communicate', 'v', 'Giao tiếp / Truyền đạt', 'Technology allows people from different countries to communicate with each other easily.', 24);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (341, 6, 'Comprehend', 'v', 'Hiểu / Lĩnh hội', 'Beginners often find it difficult to comprehend complex academic texts.', 25);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (342, 6, 'Conclude', 'v', 'Kết luận / Kết thúc', 'In the final paragraph of your essay, you should conclude your main arguments.', 26);
