INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (344, 6, 'Converse', 'v', 'Trò chuyện / Đàm đạo', 'She enjoys the opportunity to converse with native speakers to practice her pronunciation.', 28);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (345, 6, 'Define', 'v', 'Định nghĩa / Xác định rõ', 'Dictionaries help students define unfamiliar words when reading new articles.', 29);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (346, 6, 'Demonstrate', 'v', 'Chứng minh / Thể hiện / Minh họa', 'Candidates should demonstrate strong communication skills during the job interview.', 30);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (347, 6, 'Distinguish', 'v', 'Phân biệt', 'Young children can easily distinguish between different sounds in a language.', 31);
