INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (356, 6, 'Pronounce', 'v', 'Phát âm', 'It takes regular practice to pronounce English words with correct word stress.', 40);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (357, 6, 'Recall', 'v', 'Nhớ lại / Hồi tưởng', 'I can clearly recall my first day at primary school with my parents.', 41);
