INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (371, 6, 'That is to say', 'idiom', 'Tức là / Nói cách khác', 'Our company is expanding rapidly, that is to say, we need more qualified staff.', 55);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (372, 7, 'Accommodation', 'n', 'Chỗ ở / Nơi lưu trú', 'Tourists should book their hotel accommodation in advance during the peak summer holiday season.', 1);
