INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (803, 14, 'Identify', 'v', 'Nhận biết / Xác định', 'Scientists are trying to identify the main causes of global climate changes.', 56);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (804, 14, 'Improve', 'v', 'Cải thiện / Nâng cao', 'Regular physical exercise can improve both your bodily health and mental well-being.', 57);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (805, 14, 'Include', 'v', 'Bao gồm', 'A balanced daily diet should include fresh vegetables, fruits, and lean protein.', 58);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (806, 14, 'Linger', 'v', 'Kéo dài / Nán lại / Vương vấn', 'The bad smell of exhaust fumes can linger in narrow city streets for hours.', 59);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (807, 14, 'Modify', 'v', 'Sửa đổi / Điều chỉnh', 'Teachers often modify their lesson plans to suit the learning pace of each student.', 60);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (808, 14, 'Overcome', 'v', 'Vượt qua / Khắc phục', 'Students need determination and support to overcome academic pressure during final exam periods.', 61);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (809, 14, 'Present', 'v', 'Đưa ra / Gây ra / Đặt ra', 'Rapid population growth presents serious challenges for public housing and healthcare services.', 62);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (810, 14, 'Raise', 'v', 'Nâng cao / Nuôi nấng / Đưa ra', 'Schools should run awareness campaigns to raise students'' knowledge about plastic waste.', 63);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (811, 14, 'Reform', 'v', 'Cải cách / Cải tổ', 'The government decided to reform the national education system to meet modern job demands.', 64);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (812, 14, 'Regulate', 'v', 'Điều hòa / Quản lý / Quy định', 'Strict laws are needed to regulate industrial waste and protect the freshwater supply.', 65);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (813, 14, 'Remedy', 'v', 'Khắc phục / Cứu chữa / Sửa chữa', 'The local council must take immediate action to remedy the severe drinking water shortage.', 66);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (814, 14, 'Resolve', 'v', 'Giải quyết / Xử lý', 'Both sides met to resolve their differences and reach a peaceful agreement.', 67);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (815, 14, 'Tackle', 'v', 'Giải quyết / Xử lý', 'The city has launched several community projects to tackle air pollution effectively.', 68);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (816, 14, 'Tolerate', 'v', 'Chịu đựng / Tha thứ / Chấp nhận', 'Residents should not tolerate illegal garbage dumping near public parks and schools.', 69);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (817, 14, 'Transform', 'v', 'Biến đổi / Thay đổi hoàn toàn', 'Digital technology has transformed how people work, communicate, and study today.', 70);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (818, 14, 'Worsen', 'v', 'Trở nên tồi tệ hơn / Làm xấu đi', 'Heavy rains can worsen the traffic jams in large metropolitan areas.', 71);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (819, 14, 'Find a solution', 'v', 'Tìm ra giải pháp', 'Scientists are working hard to find a solution to clean energy storage problems.', 72);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (820, 14, 'Overcome a difficulty', 'v', 'Vượt qua khó khăn', 'With encouragement from her teacher, she managed to overcome a difficulty in mathematics.', 73);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (821, 14, 'Reach / find a compromise', 'v', 'Đạt được sự thỏa hiệp / Thống nhất chung', 'The management and workers must reach a compromise on working hours and overtime pay.', 74);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (822, 14, 'Remedy a situation', 'v', 'Khắc phục tình trạng / Cứu vãn tình thế', 'The school introduced free tutoring classes to remedy a situation of falling student grades.', 75);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (823, 14, 'Resolve an issue', 'v', 'Giải quyết một vấn đề', 'Open communication between parents and teenagers can help resolve an issue at home.', 76);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (824, 15, 'Acid rain', 'n', 'Mưa axit', 'Acid rain can damage historical stone buildings and harm freshwater wildlife.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (825, 15, 'Biodiversity', 'n', 'Đa dạng sinh học', 'Deforestation in tropical rainforests threatens the rich biodiversity of these unique regions.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (826, 15, 'Climate change', 'n', 'Biến đổi khí hậu', 'Rising ocean temperatures are one of the clearest signs of global climate change.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (827, 15, 'Contamination', 'n', 'Sự ô nhiễm / Sự nhiễm bẩn', 'Chemical waste from nearby factories caused serious water contamination in the river.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (828, 15, 'Deforestation', 'n', 'Nạn phá rừng / Sự tàn phá rừng', 'Deforestation causes severe soil erosion and destroys natural habitats of wild animals.', 5);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (829, 15, 'Disposal', 'n', 'Sự vứt bỏ / Sự xử lý (rác thải)', 'Safe disposal of medical waste is essential to prevent dangerous infections in hospitals.', 6);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (830, 15, 'Drought', 'n', 'Hạn hán', 'The severe drought destroyed rice crops and left many local farmers without income.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (831, 15, 'Ecosystem', 'n', 'Hệ sinh thái', 'Protecting coral reefs is vital because they support a diverse marine ecosystem.', 8);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (832, 15, 'Emission', 'n', 'Sự phát thải / Khí thải', 'Strict regulations on carbon emission can encourage companies to use greener technologies.', 9);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (833, 15, 'The environment', 'n', 'Môi trường tự nhiên / Môi trường sống', 'Using public transport instead of private cars helps protect the environment from pollution.', 10);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (834, 15, 'Erosion', 'n', 'Sự xói mòn / Sự ăn mòn', 'Planting trees along riverbanks helps prevent soil erosion caused by heavy rains.', 11);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (835, 15, 'Exhaust (fumes)', 'n', 'Khí thải (động cơ / xe cộ)', 'Breathing in exhaust fumes from heavy traffic can harm the human respiratory system.', 12);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (836, 15, 'Fertilizer', 'n', 'Phân bón', 'Farmers are encouraged to use organic fertilizer to protect soil quality and groundwater.', 13);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (837, 15, 'Flood', 'n', 'Lũ lụt / Trận lụt', 'The heavy storm caused a sudden flood that damaged many homes and roads.', 14);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (838, 15, 'Food chain', 'n', 'Chuỗi thức ăn', 'Microplastics in the ocean are now entering the global food chain through fish.', 15);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (839, 15, 'Fumes', 'n', 'Khói / Khói độc / Hơi độc', 'Workers in the chemical factory must wear masks to avoid inhaling toxic fumes.', 16);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (840, 15, 'Greenhouse gases', 'n', 'Khí nhà kính', 'The burning of fossil fuels releases huge amounts of greenhouse gases into the atmosphere.', 17);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (841, 15, 'Impact', 'n', 'Tác động / Sự ảnh hưởng', 'Mass tourism can have a negative impact on delicate local environments and cultures.', 18);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (842, 15, 'Pollutant', 'n', 'Chất gây ô nhiễm', 'Plastic is a dangerous pollutant that takes hundreds of years to break down completely.', 19);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (843, 15, 'Pollution', 'n', 'Sự ô nhiễm', 'Air pollution in major cities poses a serious threat to public health and safety.', 20);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (844, 15, 'Process', 'n', 'Quy trình / Quá trình', 'Recycling paper is a simple process that helps save trees and reduce industrial waste.', 21);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (845, 15, 'Refuse', 'n', 'Rác thải / Phế thải', 'The city collects household refuse twice a week to keep residential streets clean.', 22);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (846, 15, 'Strain', 'n', 'Sự căng thẳng / Áp lực lớn', 'Rapid urban growth puts a heavy strain on public transport and healthcare services.', 23);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (847, 15, 'Threat', 'n', 'Mối đe dọa / Mối nguy cơ', 'Habitat loss is currently the biggest threat facing endangered wildlife species worldwide.', 24);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (848, 15, 'Waste', 'n', 'Rác thải / Sự lãng phí', 'Households should separate plastic waste from organic waste to support recycling efforts.', 25);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (849, 15, 'Achievable', 'adj', 'Có thể đạt được / Khả thi', 'Reducing single-use plastic in daily life is an achievable goal for every family.', 26);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (850, 15, 'Advantageous', 'adj', 'Có lợi / Thuận lợi', 'Studying abroad can be very advantageous for students seeking international career opportunities.', 27);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (851, 15, 'At risk', 'adj', 'Có nguy cơ / Đang gặp nguy hiểm', 'Many polar animals are at risk of extinction due to melting Arctic sea ice.', 28);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (852, 15, 'Beneficial', 'adj', 'Có lợi / Mang lại lợi ích', 'Eating plenty of fresh vegetables is beneficial to your digestive health and immunity.', 29);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (853, 15, 'Chronic', 'adj', 'Mãn tính / Kinh niên / Kéo dài', 'Exposure to toxic fumes can lead to chronic breathing problems in factory workers.', 30);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (854, 15, 'Conceivable', 'adj', 'Có thể tưởng tượng được / Có thể hình dung', 'Solar energy is suitable for almost every conceivable type of modern building design.', 31);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (855, 15, 'Contaminated', 'adj', 'Bị ô nhiễm / Bị nhiễm bẩn', 'Drinking contaminated water can cause serious stomach infections and other severe illnesses.', 32);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (856, 15, 'Devastating', 'adj', 'Có tính tàn phá / Khốc liệt', 'The major oil spill had a devastating effect on marine life along the coastline.', 33);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (857, 15, 'Doubtful', 'adj', 'Nghi ngờ / Không chắc chắn', 'It is doubtful that fossil fuel supplies will last until the next century.', 34);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (858, 15, 'Environmental', 'adj', 'Thuộc về môi trường', 'Air pollution is a pressing environmental issue that affects millions of urban citizens.', 35);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (859, 15, 'Environmentally friendly', 'adj', 'Thân thiện với môi trường', 'Riding a bicycle to work is an environmentally friendly way to stay fit and healthy.', 36);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (860, 15, 'Feasible', 'adj', 'Khả thi / Có thể thực hiện được', 'Building a solar-powered school is a feasible project for the local community.', 37);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (861, 15, 'Fruitless', 'adj', 'Không có kết quả / Vô ích / Thất bại', 'Their attempts to clean the river proved fruitless without strict government factory regulations.', 38);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (862, 15, 'Futile', 'adj', 'Vô ích / Không có kết quả', 'It is futile to plant new trees without protecting them from illegal logging activities.', 39);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (863, 15, 'Immune', 'adj', 'Miễn dịch / Miễn nhiễm / Không bị ảnh hưởng', 'A healthy diet helps keep your immune system strong against common seasonal infections.', 40);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (864, 15, 'Impracticable', 'adj', 'Không khả thi / Không thể thực hiện được', 'Banning all private cars immediately is impracticable for a city without good bus networks.', 41);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (865, 15, 'Improbable', 'adj', 'Khó xảy ra / Không chắc chắn', 'It seems improbable that the global temperature will drop without international climate agreements.', 42);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (866, 15, 'In danger (of)', 'adj', 'Có nguy cơ / Gặp nguy hiểm', 'Many rare tropical bird species are in danger of extinction due to widespread deforestation.', 43);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (867, 15, 'Insoluble', 'adj', 'Không thể giải quyết được / Không tan', 'Traffic congestion seems like an insoluble problem for many overcrowded modern megacities.', 44);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (868, 15, 'Irreparable', 'adj', 'Không thể cứu vãn / Không thể khắc phục', 'Oil spills cause irreparable damage to marine life and delicate coastal ecosystems.', 45);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (869, 15, 'Irreplaceable', 'adj', 'Không thể thay thế / Vô giá', 'Ancient rainforests are irreplaceable natural treasures that take centuries to grow back.', 46);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (870, 15, 'Irreversible', 'adj', 'Không thể đảo ngược / Không thể thay đổi lại', 'Melting polar glaciers could cause irreversible changes to global weather and sea levels.', 47);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (871, 15, 'Liable', 'adj', 'Có khả năng bị / Có trách nhiệm pháp lý', 'Drivers who cause traffic accidents are liable for all property damage and medical costs.', 48);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (872, 15, 'Life-threatening', 'adj', 'Đe dọa tính mạng / Nguy hiểm đến tính mạng', 'Severe air pollution can cause life-threatening illnesses such as asthma and heart disease.', 49);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (873, 15, 'Pervasive', 'adj', 'Lan tỏa khắp nơi / Tràn lan', 'Plastic waste has become a pervasive environmental problem found even on remote islands.', 50);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (874, 15, 'Pointless', 'adj', 'Vô nghĩa / Không có mục đích', 'It is pointless to clean the beach if visitors continue leaving plastic rubbish behind.', 51);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (875, 15, 'Pristine', 'adj', 'Nguyên sơ / Trong lành / Còn nguyên vẹn', 'Tourists are attracted to the island because of its pristine beaches and clear waters.', 52);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (876, 15, 'Questionable', 'adj', 'Đáng nghi ngờ / Còn gây tranh cãi', 'The safety of building chemical factories near residential areas remains highly questionable.', 53);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (877, 15, 'Recyclable', 'adj', 'Có thể tái chế', 'We should use recyclable shopping bags to cut down on plastic household waste.', 54);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (878, 15, 'Sustainable', 'adj', 'Bền vững / Thân thiện với môi trường', 'Using solar and wind energy is essential for sustainable economic development today.', 55);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (879, 15, 'Taxing', 'adj', 'Đòi hỏi nhiều nỗ lực / Căng thẳng / Nặng nhọc', 'Working long hours in a busy hospital can be mentally and physically taxing.', 56);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (880, 15, 'Unattainable', 'adj', 'Không thể đạt được / Xa vời', 'Zero waste may seem like an unattainable goal, but small daily efforts help significantly.', 57);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (881, 15, 'Unlikely', 'adj', 'Không có khả năng xảy ra / Khó có thể', 'It is unlikely that electric cars will replace all petrol vehicles within five years.', 58);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (882, 15, 'Unprecedented', 'adj', 'Chưa từng có / Chưa từng thấy', 'The country experienced an unprecedented heatwave that broke all previous summer temperature records.', 59);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (883, 15, 'Useless', 'adj', 'Vô ích / Không có tác dụng', 'Buying products with excessive plastic packaging is useless if we want to protect the environment.', 60);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (884, 15, 'Viable', 'adj', 'Khả thi / Có thể thực hiện được', 'Solar energy is becoming a viable alternative to fossil fuels in many developing countries.', 61);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (885, 15, 'Vital', 'adj', 'Thiết yếu / Cực kỳ quan trọng', 'Clean water plays a vital role in maintaining public health and preventing dangerous diseases.', 62);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (886, 15, 'Worthwhile', 'adj', 'Đáng giá / Bổ ích', 'Volunteering for local environmental projects is a worthwhile experience for young students.', 63);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (887, 15, 'Confront', 'v', 'Đối mặt / Đương đầu', 'Governments must confront serious environmental challenges before the situation becomes much worse.', 64);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (888, 15, 'Contaminate', 'v', 'Làm ô nhiễm / Làm nhiễm bẩn', 'Chemical waste from factories can easily contaminate nearby rivers and underground water sources.', 65);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (889, 15, 'Dispose of', 'v', 'Vứt bỏ / Xử lý (rác thải)', 'People should learn how to dispose of plastic items properly to reduce environmental damage.', 66);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (890, 15, 'Dump', 'v', 'Vứt bỏ / Đổ (rác thải)', 'Many companies illegally dump untreated industrial waste into the ocean to save money.', 67);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (891, 15, 'Threaten', 'v', 'Đe dọa', 'Rising sea levels threaten many coastal cities and agricultural areas around the world.', 68);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (892, 15, 'Inexorably', 'v', 'Không thể ngăn cản / Một cách tất yếu', 'Global temperatures continue to rise inexorably because of high greenhouse gas emissions.', 69);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (893, 15, 'Inevitably', 'v', 'Chắc chắn xảy ra / Tất yếu', 'Rapid urbanization will inevitably lead to serious traffic congestion and severe air pollution.', 70);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (894, 16, 'Atmosphere', 'n', 'Khí quyển / Bầu không khí', 'Large amounts of harmful gases are released into the atmosphere every single day.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (895, 16, 'Balance', 'n', 'Sự cân bằng', 'Human activities have disrupted the natural balance of ecosystems across the planet.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (896, 16, 'Biofuel', 'n', 'Nhiên liệu sinh học', 'Many scientists believe that biofuel made from plants can replace traditional fossil fuels.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (897, 16, 'Carbon', 'n', 'Cacbon', 'Countries around the world are trying to reduce their total carbon footprint significantly.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (898, 16, 'Carbon dioxide', 'n', 'Khí cacbonic / Khí CO2', 'Trees play an important role because they absorb carbon dioxide and release fresh oxygen.', 5);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (899, 16, 'Crisis', 'n', 'Khủng hoảng / Cuộc khủng hoảng', 'The global energy crisis has forced many nations to invest in renewable energy sources.', 6);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (900, 16, 'Electricity', 'n', 'Điện / Điện năng', 'Using solar panels allows households to generate their own clean electricity and save money.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (901, 16, 'Emissions', 'n', 'Khí thải', 'Governments should introduce strict laws to limit harmful emissions from cars and factories.', 8);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (902, 16, 'Exhaust', 'n', 'Khí thải (xe cộ) / Khói xả', 'Vehicle exhaust is one of the main causes of poor air quality in modern cities.', 9);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (903, 16, 'Fossil fuel', 'n', 'Nhiên liệu hóa thạch', 'Burning fossil fuel releases dangerous greenhouse gases that contribute directly to global warming.', 10);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (904, 16, 'Fuel', 'n', 'Nhiên liệu / Chất đốt', 'Rising fuel prices have encouraged more commuters to switch to public transport.', 11);
