INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1012, 17, 'Unemployed', 'adj', 'Thất nghiệp / Không có việc làm', 'The government provides monthly financial allowances to help unemployed citizens find work.', 69);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1013, 17, 'Unskilled', 'adj', 'Lao động phổ thông / Không đòi hỏi tay nghề', 'Automation is rapidly replacing many unskilled jobs in factories across the world.', 70);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1014, 17, 'Apply', 'v', 'Nộp đơn (xin việc, học) / Áp dụng', 'Graduates are encouraged to apply for jobs that match their university degrees.', 71);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1015, 17, 'Compete', 'v', 'Cạnh tranh / Tranh tài', 'Small local stores have to compete against large international supermarket chains.', 72);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1016, 17, 'Earn', 'v', 'Kiếm được (tiền, sự tôn trọng)', 'He works hard every day to earn enough money for his children''s education.', 73);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1017, 17, 'Endorse', 'v', 'Quảng cáo đại diện / Tán thành, ủng hộ', 'Famous sports stars often endorse expensive brands to promote products to teenagers.', 74);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1018, 17, 'Invest (in)', 'v', 'Đầu tư (vào)', 'Governments should invest in public transportation to reduce severe traffic congestion in cities.', 75);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1019, 17, 'Persuade', 'v', 'Thuyết phục', 'Good advertisements can persuade customers to try new products in the market.', 76);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1020, 17, 'To be promoted', 'v', 'Được thăng chức', 'She worked very hard and was pleased to be promoted to senior manager.', 77);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1021, 17, 'Request', 'v', 'Yêu cầu / Đề nghị', 'Employees can request flexible working hours to maintain a healthy work-life balance.', 78);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1022, 17, 'Retire', 'v', 'Nghỉ hưu', 'My grandfather decided to retire early so that he could enjoy gardening peacefully.', 79);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1023, 18, 'Actions', 'n', 'Hành động / Biện pháp hành động', 'Governments must take immediate legal actions against companies that pollute local rivers.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1024, 18, 'Arson', 'n', 'Tội cố ý phóng hỏa / Sự phóng hỏa', 'The police arrested a suspect for committing arson at an empty warehouse.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1025, 18, 'Authority', 'n', 'Cơ quan chức năng / Thẩm quyền', 'The local authority decided to build more parks and leisure centers for residents.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1026, 18, 'Burglary', 'n', 'Tội đột nhập trộm cắp / Vụ trộm nhà', 'Installing modern security cameras helps protect private houses against burglary during vacations.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1027, 18, 'Consequences', 'n', 'Hậu quả / Hệ quả', 'Young people need to understand the serious legal consequences of committing violent crimes.', 5);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1028, 18, 'Convict', 'n', 'Người bị kết án / Tù nhân', 'Former convicts often struggle to find stable jobs after leaving prison.', 6);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1029, 18, 'Crime', 'n', 'Tội phạm / Tội ác', 'Poverty and lack of education often lead to higher levels of violent crime.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1030, 18, 'Crime rate', 'n', 'Tỷ lệ tội phạm', 'Installing bright streetlights has helped decrease the crime rate in this neighborhood.', 8);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1031, 18, 'Criminal', 'n', 'Tội phạm / Kẻ phạm tội', 'The police caught the dangerous criminal within twenty-four hours after the robbery.', 9);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1032, 18, 'Deterrent', 'n', 'Biện pháp răn đe / Yếu tố ngăn chặn', 'Heavy fines can serve as an effective deterrent against speeding on busy roads.', 10);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1033, 18, 'Evidence', 'n', 'Bằng chứng / Chứng cứ', 'The detective gathered clear physical evidence to identify the suspect of the crime.', 11);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1034, 18, 'Fine', 'n', 'Tiền phạt', 'Drivers who park their cars in prohibited areas must pay a heavy fine.', 12);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1035, 18, 'Fraud', 'n', 'Tội lừa đảo / Sự gian lận', 'Online fraud has become a growing concern for banks and their digital customers.', 13);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1036, 18, 'Imprisonment', 'n', 'Án tù / Sự phạt tù / Sự giam giữ', 'The judge sentenced the corrupt official to ten years of imprisonment.', 14);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1037, 18, 'Inequality', 'n', 'Sự bất bình đẳng', 'Social inequality often leads to frustration and contributes to social instability and crime.', 15);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1038, 18, 'Intent', 'n', 'Ý định / Ý đồ (phạm tội)', 'The prosecution must prove that the suspect acted with clear criminal intent.', 16);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1039, 18, 'Intrusion', 'n', 'Sự xâm phạm / Sự xâm nhập trái phép', 'Excessive surveillance is often seen as an unnecessary intrusion into private personal life.', 17);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1040, 18, 'Judge', 'n', 'Thẩm phán / Quan tòa', 'The judge listened to both lawyers before delivering a fair and final verdict.', 18);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1041, 18, 'Jury', 'n', 'Bồi thẩm đoàn', 'The jury listened to the witnesses carefully before reaching their final decision.', 19);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1042, 18, 'Kidnapping', 'n', 'Tội bắt cóc / Vụ bắt cóc', 'The government introduced strict laws to prevent cases of child kidnapping in cities.', 20);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1043, 18, 'Lawyer', 'n', 'Luật sư', 'Every person has the legal right to consult an experienced lawyer before trial.', 21);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1044, 18, 'Motive', 'n', 'Động cơ (phạm tội)', 'The police are still investigating the real motive behind the armed bank robbery.', 22);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1045, 18, 'Murder', 'n', 'Tội giết người / Vụ án mạng', 'The suspect was charged with murder and faced a potential life sentence.', 23);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1046, 18, 'Offence', 'n', 'Hành vi phạm tội / Tội phạm', 'Driving without a valid license is considered a serious legal offence in most nations.', 24);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1047, 18, 'Pickpocketing', 'n', 'Tội móc túi / Nạn móc túi', 'Tourists should watch their belongings carefully to avoid pickpocketing on crowded trains.', 25);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1048, 18, 'Prevention', 'n', 'Sự phòng ngừa / Sự ngăn chặn', 'Crime prevention requires close cooperation between local communities and the police force.', 26);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1049, 18, 'Prison', 'n', 'Nhà tù / Trại giam', 'Many countries are reforming their prison systems to focus on prisoner rehabilitation.', 27);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1050, 18, 'Prisoner', 'n', 'Tù nhân', 'Prisoners are offered educational courses to help them find employment after release.', 28);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1051, 18, 'Property crime', 'n', 'Tội xâm phạm quyền sở hữu / Tội phạm tài sản', 'Better street lighting helps reduce property crime such as burglary and vehicle theft.', 29);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1052, 18, 'Prosecutor', 'n', 'Công tố viên / Kiểm sát viên', 'The prosecutor presented solid evidence to convince the court of the defendant''s guilt.', 30);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1053, 18, 'Protection', 'n', 'Sự bảo vệ', 'Witnesses in dangerous criminal investigations often receive round-the-clock police protection.', 31);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1054, 18, 'Punishment', 'n', 'Hình phạt / Sự trừng phạt', 'Community service is often used as a punishment for minor first-time offences.', 32);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1055, 18, 'Recklessness', 'n', 'Sự liều lĩnh / Tính bất cẩn, coi thường nguy hiểm', 'His recklessness behind the wheel caused a severe traffic accident yesterday afternoon.', 33);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1056, 18, 'Smuggling', 'n', 'Tội buôn lậu / Sự buôn lậu', 'Customs officers work tirelessly at border checkpoints to combat illegal drug smuggling.', 34);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1057, 18, 'Social system', 'n', 'Hệ thống xã hội', 'A fair legal framework is essential for maintaining order in every social system.', 35);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1058, 18, 'Swearing', 'n', 'Hành vi chửi thề / Lời nói tục tĩu', 'Swearing in public places or school classrooms is considered rude and unacceptable behavior.', 36);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1059, 18, 'The accused', 'n', 'Bị cáo / Người bị buộc tội', 'The accused firmly stated that he was far away when the incident happened.', 37);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1060, 18, 'Toxic waste', 'n', 'Chất thải độc hại', 'Factories that illegally dump toxic waste into rivers should receive extremely heavy penalties.', 38);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1061, 18, 'Vandalism', 'n', 'Hành vi phá hoại của công / Tội phá hoại tài sản', 'The city council spent substantial money repairing bus stops damaged by youth vandalism.', 39);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1062, 18, 'Victim', 'n', 'Nạn nhân', 'Support programs are available to help crime victims recover both physically and emotionally.', 40);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1063, 18, 'Violation', 'n', 'Sự vi phạm / Hành vi vi phạm', 'Exceeding the speed limit in school zones is a serious violation of traffic laws.', 41);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1064, 18, 'Criminal', 'adj', 'Thuộc về hình sự / Phạm pháp', 'He was arrested by the police due to continuous involvement in criminal activities.', 42);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1065, 18, 'Drug-related', 'adj', 'Liên quan đến ma túy', 'Police launched an intensive campaign to tackle drug-related crimes in urban centers.', 43);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1066, 18, 'Evil', 'adj', 'Độc ác / Tàn ác', 'Society strongly condemns such evil behavior that causes deep pain to innocent people.', 44);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1067, 18, 'Guilty', 'adj', 'Có tội / Cảm thấy có lỗi', 'The jury declared the driver guilty of causing the accident while using his phone.', 45);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1068, 18, 'Harsh', 'adj', 'Khắc nghiệt / Nặng nề (hình phạt)', 'Some legal experts argue that harsh prison sentences do not effectively deter young offenders.', 46);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1069, 18, 'Innocent', 'adj', 'Vô tội / Trong sạch', 'The court finally declared him innocent after decisive new evidence came to light.', 47);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1070, 18, 'Intentional', 'adj', 'Cố ý / Có chủ đích', 'The official report concluded that the property damage was intentional rather than accidental.', 48);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1071, 18, 'Law-abiding', 'adj', 'Tuân thủ pháp luật / Tôn trọng luật pháp', 'Most law-abiding citizens respect community regulations and contribute to a peaceful society.', 49);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1072, 18, 'Non-violent', 'adj', 'Phi bạo lực / Không dùng bạo lực', 'Judges often sentence non-violent offenders to community service rather than long prison terms.', 50);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1073, 18, 'Offensive', 'adj', 'Xúc phạm / Phản cảm', 'Using offensive language during online discussions can result in your account being suspended.', 51);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1074, 18, 'On trial', 'adj', 'Đang bị hầu tòa / Đang bị xét xử', 'The former company director is currently on trial for accepting massive corporate bribes.', 52);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1075, 18, 'Petty (crime)', 'adj', 'Vặt vãnh / Nhỏ (tội phạm nhỏ)', 'Petty crime like shoplifting is common in crowded shopping centers during holiday seasons.', 53);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1076, 18, 'Punishable', 'adj', 'Có thể bị xử phạt / Đáng bị trừng phạt', 'Driving without wearing a safety belt is punishable by a substantial monetary fine.', 54);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1077, 18, 'Random', 'adj', 'Ngẫu nhiên', 'Traffic police officers carry out random alcohol breath tests on drivers every weekend.', 55);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1078, 18, 'Strict', 'adj', 'Nghiêm ngặt / Khắt khe', 'The government should enforce strict environmental regulations to reduce industrial pollution.', 56);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1079, 18, 'Unintentional', 'adj', 'Vô ý / Không cố ý', 'Many car accidents are unintentional and occur because drivers are tired or distracted.', 57);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1080, 18, 'Victimless', 'adj', 'Không có nạn nhân', 'Some people believe that illegal downloading is a victimless crime, but artists lose money.', 58);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1081, 18, 'Abide (by)', 'v', 'Tuân theo / Chấp hành', 'All citizens must abide by the law to keep their community safe and peaceful.', 59);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1082, 18, 'Abolish', 'v', 'Bãi bỏ / Hủy bỏ', 'Several countries decided to abolish the death penalty and replace it with life imprisonment.', 60);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1083, 18, 'Combat', 'v', 'Đấu tranh chống lại / Ngăn chặn', 'The government is trying to combat crime by installing more security cameras in public areas.', 61);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1084, 18, 'Deter', 'v', 'Răn đe / Ngăn chặn', 'Heavy fines can deter drivers from speeding and help reduce serious road accidents.', 62);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1085, 18, 'Enforce', 'v', 'Thực thi / Bắt buộc tuân thủ', 'The local police strictly enforce traffic laws to protect pedestrians and reduce road accidents.', 63);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1086, 18, 'Imprison', 'v', 'Bỏ tù / Tống giam', 'The court decided to imprison the criminal for five years for violent robbery.', 64);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1087, 18, 'Monitor', 'v', 'Giám sát / Theo dõi', 'Parents should monitor how much time their children spend on social media every day.', 65);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1088, 18, 'Obey', 'v', 'Tuân theo / Nghe lời', 'Young drivers must learn to obey traffic regulations to prevent dangerous accidents on roads.', 66);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1089, 18, 'Offend', 'v', 'Phạm tội / Vi phạm pháp luật / Làm xúc phạm', 'Many teenagers who offend for the first time receive community service instead of prison.', 67);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1090, 18, 'Perpetrate', 'v', 'Phạm (tội) / Gây ra (hành vi xấu)', 'Criminals who perpetrate violent crimes against innocent citizens deserve to receive harsh punishments.', 68);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1091, 18, 'Prevent', 'v', 'Ngăn chặn / Ngăn ngừa', 'Good education and stable jobs can help prevent young people from committing crimes.', 69);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1092, 18, 'Protect', 'v', 'Bảo vệ / Che chở', 'The primary duty of police officers is to protect citizens from dangerous criminals.', 70);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1093, 18, 'Prove', 'v', 'Chứng minh / Chứng tỏ', 'The prosecutor could not prove that the suspect was present at the crime scene.', 71);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1094, 18, 'Punish', 'v', 'Trừng phạt / Xử phạt', 'Schools should punish students who bully others to create a safe learning environment.', 72);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1095, 18, 'Resent', 'v', 'Bực bội / Phẫn uất / Không bằng lòng', 'Many citizens resent paying higher taxes when public services do not improve significantly.', 73);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1096, 18, 'Respect', 'v', 'Tôn trọng / Kính trọng / Tuân thủ', 'Everyone must respect the law and treat other members of the community fairly.', 74);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1097, 18, 'Violate', 'v', 'Vi phạm / Xâm phạm', 'Companies that violate environmental regulations should be forced to pay heavy financial penalties.', 75);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1098, 18, 'Accept the consequences', 'v', 'Chấp nhận hậu quả', 'If teenagers break school rules, they must accept the consequences of their bad actions.', 76);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1099, 18, 'Commit a crime', 'v', 'Phạm tội', 'People who commit a crime should be given a chance to reform their lives.', 77);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1100, 18, 'Convict a criminal', 'v', 'Kết án phạm nhân / Kết tội kẻ phạm tội', 'The court needs clear and convincing evidence before it can convict a criminal.', 78);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1101, 18, 'Impose a fine', 'v', 'Phạt tiền / Áp dụng mức phạt tiền', 'The traffic police will impose a fine on anyone who drives through a red light.', 79);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1102, 18, 'Pass a law', 'v', 'Thông qua một đạo luật / Ban hành luật', 'The government should pass a law to ban single-use plastic bags in all supermarkets.', 80);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1103, 18, 'Solve a crime', 'v', 'Phá án / Giải quyết vụ án', 'Police detectives used modern camera footage and fingerprints to solve a difficult crime.', 81);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1104, 19, 'Access', 'n', 'Quyền truy cập / Sự tiếp cận', 'Students living in remote areas need free internet access to complete their online homework.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1105, 19, 'Attitude', 'n', 'Thái độ / Quan điểm', 'Having a positive attitude towards learning can help university students achieve academic success.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1106, 19, 'Author', 'n', 'Tác giả / Nhà văn', 'The author wrote an inspiring book about how modern technology changes our daily lifestyle.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1107, 19, 'Bias', 'n', 'Sự thiên vị / Thành kiến', 'Reporters must avoid political bias and present facts fairly to all their readers.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1108, 19, 'Censorship', 'n', 'Sự kiểm duyệt', 'Strict government censorship can sometimes prevent journalists from reporting truthful news about society.', 5);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1109, 19, 'Challenge', 'n', 'Thử thách / Thách thức', 'Finding a balance between work and family life is a major challenge for working parents.', 6);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1110, 19, 'Credibility', 'n', 'Độ tin cậy / Sự tín nhiệm', 'Publishing fake news damages the credibility of newspapers and makes readers lose their trust.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1111, 19, 'Current affairs', 'n', 'Thời sự / Các vấn đề hiện nay', 'Watching current affairs programmes helps young people stay informed about global economic issues.', 8);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1112, 19, 'Editor', 'n', 'Biên tập viên / Chủ bút', 'The newspaper editor checks every article carefully to ensure all facts are completely accurate.', 9);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1113, 19, 'Exposé', 'n', 'Bài phóng sự điều tra / Phóng sự phơi bày sự thật', 'The journalist published an exposé revealing how the factory secretly dumped toxic chemicals into rivers.', 10);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1114, 19, 'Exposure', 'n', 'Sự tiếp xúc / Sự phơi bày', 'Early exposure to foreign languages helps young children develop their communication skills faster.', 11);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1115, 19, 'Fame', 'n', 'Danh tiếng / Tiếng tăm', 'Many young singers seek international fame without realizing how stressful public life can be.', 12);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1116, 19, 'Free press', 'n', 'Báo chí tự do', 'A free press is essential in a democratic society to hold powerful leaders accountable.', 13);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1117, 19, 'Ideology', 'n', 'Hệ tư tưởng', 'The political party promotes an economic ideology that emphasizes free trade and private investment.', 14);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1118, 19, 'Influence', 'n', 'Sự ảnh hưởng / Tác động', 'Social media has a powerful influence on the shopping habits of young consumers today.', 15);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1119, 19, 'The Internet', 'n', 'Mạng Internet', 'The Internet allows university students to access valuable academic research materials from anywhere.', 16);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1120, 19, 'Investigation', 'n', 'Cuộc điều tra / Sự điều tra', 'The police launched an official investigation into the recent bank robbery downtown.', 17);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1121, 19, 'Issue', 'n', 'Vấn đề / Số báo', 'Air pollution has become an urgent environmental issue in many large modern cities.', 18);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1122, 19, 'Journal', 'n', 'Tạp chí chuyên ngành / Nhật ký', 'She published her medical research findings in a respected international science journal.', 19);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1123, 19, 'Journalism', 'n', 'Nghề làm báo / Báo chí', 'Honest and objective journalism plays a vital role in keeping citizens well informed.', 20);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1124, 19, 'Mass media', 'n', 'Truyền thông đại chúng', 'The mass media has a strong influence on public opinions regarding environmental protection.', 21);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1125, 19, 'Media', 'n', 'Truyền thông / Phương tiện truyền thông', 'Traditional media such as newspapers and radio are losing popularity to online platforms.', 22);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1126, 19, 'Network', 'n', 'Mạng lưới / Hệ thống truyền hình', 'The television network broadcasts educational programs for children every weekend morning.', 23);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1127, 19, 'The news', 'n', 'Tin tức / Bản tin', 'Many elderly people still prefer watching the news on television every evening.', 24);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1128, 19, 'Newspaper', 'n', 'Tờ báo / Báo giấy', 'My grandfather likes reading a printed newspaper while having his morning breakfast.', 25);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1129, 19, 'Newsstand', 'n', 'Sạp báo / Quầy báo', 'He bought a travel magazine at the local newsstand before boarding the train.', 26);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1130, 19, 'Opinion', 'n', 'Ý kiến / Quan điểm', 'Students should feel free to express their personal opinion during group classroom discussions.', 27);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1131, 19, 'Paparazzi', 'n', 'Thợ săn ảnh / Tay săn ảnh người nổi tiếng', 'Aggressive paparazzi often follow movie stars and disturb their personal family life.', 28);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1132, 19, 'Press', 'n', 'Báo chí / Giới báo chí', 'The company president held a press conference to introduce their new technological product.', 29);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1133, 19, 'Privacy', 'n', 'Sự riêng tư / Quyền riêng tư', 'Many smartphone users worry about their digital privacy when using social networking applications.', 30);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1134, 19, 'Publication', 'n', 'Ấn phẩm / Sự xuất bản', 'The university releases an academic publication every month to share scientific discoveries.', 31);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1135, 19, 'Publicity', 'n', 'Sự chú ý của công chúng / Sự quảng bá', 'The environmental campaign received widespread publicity after several famous actors supported it.', 32);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1136, 19, 'Publisher', 'n', 'Nhà xuất bản / Người xuất bản', 'The book publisher decided to print ten thousand copies of the new English dictionary.', 33);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1137, 19, 'Relevance', 'n', 'Sự liên quan / Tính thích hợp', 'University courses should have direct relevance to the current demands of the job market.', 34);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1138, 19, 'Safeguard', 'n', 'Biện pháp bảo vệ / Biện pháp an toàn', 'Strong passwords and authentication tools serve as an essential safeguard against cyber attacks.', 35);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1139, 19, 'Source', 'n', 'Nguồn / Nguồn tin', 'Students must cite every information source accurately when writing an academic research paper.', 36);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1140, 19, 'Speculation', 'n', 'Sự suy đoán / Phỏng đoán', 'There was widespread media speculation about which actor would win the major film award.', 37);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1141, 19, 'Tabloid', 'n', 'Báo lá cải / Báo khổ nhỏ', 'Tabloid newspapers often print sensational stories about celebrity relationships to attract readers.', 38);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1142, 19, 'The Web', 'n', 'Mạng internet / Mạng toàn cầu', 'You can find a vast amount of educational resources for free on the Web.', 39);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1143, 19, 'Alternative', 'adj', 'Thay thế / Khác', 'Many governments are investing in alternative energy sources like solar and wind power.', 40);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1144, 19, 'Artificial', 'adj', 'Nhân tạo', 'Parents should limit foods containing artificial colours and sweet chemicals to protect children''s health.', 41);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1145, 19, 'Attention-grabbing', 'adj', 'Thu hút sự chú ý / Bắt mắt', 'Online advertisers create attention-grabbing headlines to persuade internet users to click their links.', 42);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1146, 19, 'Biased', 'adj', 'Thiên vị / Có thành kiến', 'Reading biased news articles can make people form unfair opinions about other cultures.', 43);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1147, 19, 'Celebrity', 'adj', 'Thuộc về người nổi tiếng', 'Young people are heavily influenced by the glamorous celebrity lifestyle shown on television.', 44);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1148, 19, 'Controversial', 'adj', 'Gây tranh cãi', 'Genetically modified food remains a controversial topic among environmental scientists and consumers.', 45);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1149, 19, 'Distorted', 'adj', 'Bị bóp méo / Xuyên tạc / Sai lệch', 'Social media can give people a distorted view of realistic beauty and healthy lifestyles.', 46);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1150, 19, 'Entertaining', 'adj', 'Có tính giải trí / Thú vị', 'The history teacher always prepares entertaining lessons that help students remember facts easily.', 47);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1151, 19, 'Factual', 'adj', 'Dựa trên sự thật / Thực tế', 'Documentaries should present factual information rather than dramatic personal assumptions.', 48);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1152, 19, 'Informative', 'adj', 'Cung cấp nhiều thông tin / Bổ ích', 'The documentary provided an informative overview of climate change and its global effects.', 49);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1153, 19, 'Intrusive', 'adj', 'Xâm phạm riêng tư / Gây phiền toái', 'Pop-up advertisements on mobile screens are often intrusive and annoy online readers.', 50);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1154, 19, 'Investigative', 'adj', 'Thuộc về điều tra', 'The newspaper won a national award for its outstanding investigative reporting on financial corruption.', 51);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1155, 19, 'Mainstream', 'adj', 'Chính thống / Chủ lưu', 'Mainstream media outlets should focus more on pressing social issues rather than celebrity gossip.', 52);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1156, 19, 'Pervasive', 'adj', 'Lan tỏa khắp nơi / Tràn ngập', 'Smartphones have a pervasive influence on modern family life and everyday social communication.', 53);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1157, 19, 'Realistic', 'adj', 'Thực tế / Hiện thực', 'Students need to set realistic study goals to avoid feeling stressed before final exams.', 54);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1158, 19, 'Sensationalist', 'adj', 'Giật gân / Câu khách', 'Many websites use sensationalist headlines just to attract clicks and increase advertising revenue.', 55);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1159, 19, 'Superficial', 'adj', 'Hời hợt / Nông cạn', 'Judging people by their physical appearance alone often leads to superficial relationships.', 56);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1160, 19, 'Unbiased', 'adj', 'Khách quan / Không thiên vị', 'Judges must remain completely unbiased when hearing arguments from both sides in court.', 57);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1161, 19, 'Well-informed', 'adj', 'Hiểu biết rộng / Được cập nhật thông tin tốt', 'Reading reliable news daily helps citizens make well-informed decisions during democratic elections.', 58);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1162, 19, 'Affect', 'v', 'Ảnh hưởng đến / Tác động đến', 'Spending too much time on digital devices can negatively affect a child''s eyesight.', 59);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1163, 19, 'Broadcast', 'v', 'Phát sóng / Truyền phát', 'National television channels broadcast important public health announcements during the viral outbreak.', 60);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1164, 19, 'Censor', 'v', 'Kiểm duyệt', 'The film board decided to censor violent scenes before releasing the movie to teenagers.', 61);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1165, 19, 'Control', 'v', 'Kiểm soát / Khống chế', 'Governments should control online content to protect young children from harmful information.', 62);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1166, 19, 'Exploit', 'v', 'Khai thác / Lợi dụng', 'Some companies exploit young unpaid interns by making them work long overtime hours.', 63);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1167, 19, 'Expose', 'v', 'Vạch trần / Phơi bày', 'Investigative journalists worked hard to expose corporate corruption and financial dishonesty.', 64);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1168, 19, 'Inform', 'v', 'Thông báo / Cung cấp thông tin', 'Teachers should regularly inform parents about their children''s academic progress at school.', 65);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1169, 19, 'Intrude', 'v', 'Xâm phạm / Làm phiền', 'Reporters should not intrude into the private lives of grieving victims after a tragedy.', 66);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1170, 19, 'Invade', 'v', 'Xâm phạm / Xâm lược', 'Paparazzi constantly invade the personal privacy of famous artists to sell scandalous photos.', 67);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1171, 19, 'Investigate', 'v', 'Điều tra / Khảo sát', 'The local police will thoroughly investigate the causes of the serious car collision.', 68);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1172, 19, 'Publicize', 'v', 'Quảng bá / Đưa ra công chúng', 'The university used social media campaigns to publicize its new environmental research program.', 69);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1173, 19, 'Publish', 'v', 'Xuất bản / Đăng tải', 'The scientific magazine will publish her latest study on renewable energy next month.', 70);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1174, 19, 'Report', 'v', 'Báo cáo / Tường thuật / Đưa tin', 'Journalists must verify all facts before they report breaking news to the public.', 71);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1175, 19, 'Review', 'v', 'Đánh giá / Xem xét lại / Ôn tập', 'The educational committee meets every year to review the secondary school English curriculum.', 72);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1176, 19, 'Verify', 'v', 'Xác minh / Kiểm chứng', 'Editors must carefully verify sources of information before publishing an article online.', 73);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1177, 20, 'Actor', 'n', 'Diễn viên / Diễn viên nam', 'The talented actor spent months preparing for his dramatic role in the historical movie.', 1);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1178, 20, 'Actress', 'n', 'Nữ diễn viên', 'She became a famous actress after winning an international award for her performance.', 2);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1179, 20, 'Aesthetics', 'n', 'Tính thẩm mỹ / Mỹ học', 'Modern architecture focuses not only on function but also on the aesthetics of the building.', 3);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1180, 20, 'Appreciation', 'n', 'Sự đánh giá cao / Sự cảm thụ / Sự trân trọng', 'Art classes help young children develop an appreciation of different painting styles.', 4);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1181, 20, 'Artefact', 'n', 'Hiện vật / Cổ vật', 'The local museum displays an ancient artefact that was discovered by local farmers.', 5);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1182, 20, 'Artist', 'n', 'Nghệ sĩ / Họa sĩ', 'The young artist used bright colours to show the beauty of the countryside.', 6);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1183, 20, 'Atmosphere', 'n', 'Bầu không khí', 'Soft music and warm lighting created a relaxing atmosphere in the new restaurant.', 7);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1184, 20, 'Audience', 'n', 'Khán giả / Thính giả', 'The audience clapped enthusiastically at the end of the school musical performance.', 8);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1185, 20, 'Ballerina', 'n', 'Nữ diễn viên múa ba lê / Nữ vũ công ba lê', 'She trained for over ten years to become a professional ballerina in the national theatre.', 9);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1186, 20, 'Ballet', 'n', 'Múa ba lê / Môn ba lê', 'Watching ballet helps many people appreciate the beauty and discipline of dance.', 10);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1187, 20, 'Carving', 'n', 'Tác phẩm chạm khắc / Nghệ thuật điêu khắc', 'The traditional wooden carving attracted many tourists visiting the craft village.', 11);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1188, 20, 'Conception', 'n', 'Quan niệm / Khái niệm / Ý niệm', 'His original conception of the art project changed after he visited the local community.', 12);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1189, 20, 'Concert', 'n', 'Buổi hòa nhạc / Buổi biểu diễn âm nhạc', 'Thousands of teenagers attended the live concert in the city stadium last night.', 13);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1190, 20, 'Crafts', 'n', 'Đồ thủ công / Nghề thủ công', 'Selling traditional crafts helps local people earn a stable income from tourism.', 14);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1191, 20, 'Creation', 'n', 'Sự sáng tạo / Tác phẩm sáng tạo', 'Each painting is a unique creation that reflects the personal emotions of the artist.', 15);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1192, 20, 'Culture', 'n', 'Văn hóa', 'Travelling abroad allows young people to learn about a completely different culture.', 16);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1193, 20, 'Emotion', 'n', 'Cảm xúc', 'Music is a powerful medium that can express deep emotion without any words.', 17);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1194, 20, 'Exhibition', 'n', 'Triển lãm / Cuộc triển lãm', 'Our teacher took us to an interesting art exhibition at the city gallery.', 18);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1195, 20, 'Expression', 'n', 'Sự biểu lộ / Sự thể hiện / Biểu cảm', 'Painting provides people with a creative form of self-expression to reduce daily stress.', 19);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1196, 20, 'Festival', 'n', 'Lễ hội', 'The annual film festival attracts famous directors and movie fans from around the world.', 20);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1197, 20, 'Gallery', 'n', 'Phòng trưng bày nghệ thuật / Triển lãm nghệ thuật', 'Many art lovers visit the national gallery every weekend to admire classical paintings.', 21);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1198, 20, 'Image', 'n', 'Hình ảnh', 'The digital image on the screen showed a peaceful sunset over the mountains.', 22);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1199, 20, 'Imagination', 'n', 'Trí tưởng tượng', 'Reading books helps children develop their imagination and improves their language skills.', 23);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1200, 20, 'Influence', 'n', 'Sự ảnh hưởng / Tầm ảnh hưởng', 'Parents have a strong influence on the musical tastes and hobbies of their children.', 24);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1201, 20, 'Inspiration', 'n', 'Nguồn cảm hứng / Cảm hứng', 'Nature is a great source of inspiration for many poets and landscape painters.', 25);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1202, 20, 'Intimacy', 'n', 'Sự thân mật / Sự gần gũi', 'The small theatre created a sense of intimacy between the actors and the audience.', 26);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1203, 20, 'Literature', 'n', 'Văn học', 'Studying classical literature helps students understand human history and moral values.', 27);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1204, 20, 'Mood', 'n', 'Tâm trạng', 'Listening to upbeat music can quickly improve your mood when you feel tired.', 28);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1205, 20, 'Musician', 'n', 'Nhạc sĩ / Người biểu diễn âm nhạc', 'The street musician played his guitar skillfully and attracted a large crowd of listeners.', 29);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1206, 20, 'Opera', 'n', 'Nhạc kịch opera / Vở opera', 'She booked two front-row tickets to watch a famous Italian opera this weekend.', 30);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1207, 20, 'Orchestra', 'n', 'Dàn nhạc giao hưởng / Dàn nhạc', 'The symphony orchestra performed classical pieces written by Beethoven and Mozart.', 31);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1208, 20, 'Painting', 'n', 'Bức tranh / Bức họa', 'This famous oil painting depicts a quiet rural village during the nineteenth century.', 32);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1209, 20, 'Performance', 'n', 'Buổi biểu diễn / Màn trình diễn', 'Their musical performance received enthusiastic applause from both the teachers and students.', 33);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1210, 20, 'The performing arts', 'n', 'Nghệ thuật biểu diễn', 'Schools should encourage students to participate in the performing arts like dance and drama.', 34);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1211, 20, 'Play', 'n', 'Vở kịch', 'Our class went to the local theatre to watch a classic Shakespeare play.', 35);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1212, 20, 'Portrait', 'n', 'Bức chân dung / Tranh chân dung', 'The artist painted a realistic portrait of the elderly woman sitting by the window.', 36);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1213, 20, 'Proportion', 'n', 'Tỷ lệ / Sự cân đối', 'Art students must learn how to draw the correct proportion of the human body.', 37);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1214, 20, 'Reflection', 'n', 'Hình ảnh phản chiếu / Sự suy ngẫm', 'Her latest sculpture is a clear reflection of modern societal challenges.', 38);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1215, 20, 'Response', 'n', 'Phản hồi / Sự hưởng ứng / Câu trả lời', 'The new public art installation received an overwhelmingly positive response from local residents.', 39);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1216, 20, 'Sculptor', 'n', 'Nhà điêu khắc', 'The talented sculptor carved a magnificent statue out of a single block of marble.', 40);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1217, 20, 'Sculpture', 'n', 'Bức điêu khắc / Nghệ thuật điêu khắc', 'The modern sculpture in the city square attracts many tourists every afternoon.', 41);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1218, 20, 'Stimulus', 'n', 'Yếu tố kích thích / Nguồn khích lệ', 'Creative activities at school provide an intellectual stimulus for curious young minds.', 42);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1219, 20, 'Style', 'n', 'Phong cách', 'The young painter developed her own unique style after studying traditional landscape art.', 43);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1220, 20, 'Taste', 'n', 'Thị hiếu / Gu thẩm mỹ / Khẩu vị', 'People have different taste in music, ranging from classical symphonies to modern pop.', 44);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1221, 20, 'Theatre', 'n', 'Nhà hát / Kịch nghệ', 'Going to the theatre allows people to experience live drama and cultural stories directly.', 45);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1222, 20, 'Theme', 'n', 'Chủ đề', 'Love and family are common themes explored in classical literature around the world.', 46);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1223, 20, 'Venue', 'n', 'Địa điểm tổ chức / Địa điểm biểu diễn', 'The concert hall was chosen as the main venue for the international music competition.', 47);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1224, 20, 'Works', 'n', 'Các tác phẩm / Tác phẩm', 'The exhibition features the early works of several influential twentieth-century artists.', 48);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1225, 20, 'Writer', 'n', 'Nhà văn / Tác giả', 'The famous writer published a new novel that immediately topped the bestseller list.', 49);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1226, 20, 'Abstract', 'adj', 'Trừu tượng', 'Many beginners find abstract paintings difficult to understand without an explanation from the artist.', 50);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1227, 20, 'Accomplished', 'adj', 'Tài hoa / Điêu luyện / Xuất sắc', 'She is an accomplished pianist who has performed with prestigious orchestras worldwide.', 51);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1228, 20, 'Aesthetic', 'adj', 'Thuộc về thẩm mỹ / Có tính thẩm mỹ', 'The historical city centre has great aesthetic value because of its preserved architecture.', 52);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1229, 20, 'Burgeoning', 'adj', 'Đang phát triển nhanh / Đang nở rộ', 'The city has a burgeoning art scene with many independent studios opening recently.', 53);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1230, 20, 'Classical', 'adj', 'Cổ điển', 'Learning classical music at an early age helps children develop concentration and patience.', 54);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1231, 20, 'Creative', 'adj', 'Sáng tạo', 'Doing creative activities such as painting or writing can effectively relieve work stress.', 55);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1232, 20, 'Cultural', 'adj', 'Thuộc về văn hóa', 'Visiting museums is an excellent way to experience the cultural heritage of a country.', 56);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1233, 20, 'Distracting', 'adj', 'Gây mất tập trung / Làm xao nhãng', 'Loud background music can be very distracting when students are preparing for exams.', 57);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1234, 20, 'Eclectic', 'adj', 'Đa dạng / Phong phú / Chiết trung', 'Her home is decorated with an eclectic mix of modern and vintage art pieces.', 58);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1235, 20, 'Electric', 'adj', 'Sôi động, đầy hào hứng / Thuộc về điện', 'The atmosphere inside the crowded concert hall was electric as the band took the stage.', 59);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1236, 20, 'Emotional', 'adj', 'Xúc động / Giàu cảm xúc', 'The emotional performance of the main singer brought tears to the eyes of the audience.', 60);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1237, 20, 'Fundamental', 'adj', 'Cơ bản / Thiết yếu / Cốt lõi', 'Drawing is a fundamental skill that every beginner must learn in art class.', 61);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1238, 20, 'Imaginative', 'adj', 'Giàu trí tưởng tượng / Sáng tạo', 'Children often write imaginative stories full of magical creatures and exciting adventures.', 62);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1239, 20, 'Influential', 'adj', 'Có ảnh hưởng lớn', 'The teacher remained an influential figure throughout my entire high school education.', 63);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1240, 20, 'Inspirational', 'adj', 'Truyền cảm hứng', 'His speech about pursuing dreams was deeply inspirational for all the graduating students.', 64);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1241, 20, 'Interactive', 'adj', 'Tương tác / Mang tính tương tác', 'The modern science museum uses interactive exhibits to make learning fun for young visitors.', 65);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1242, 20, 'Literary', 'adj', 'Thuộc về văn học', 'She joined a local literary club to discuss classic novels with fellow book lovers.', 66);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1243, 20, 'Live', 'adj', 'Trực tiếp / Sống', 'Attending a live performance offers a much more exciting experience than watching online videos.', 67);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1244, 20, 'Magical', 'adj', 'Kỳ diệu / Mê hoặc / Huyền diệu', 'The lighting and music created a truly magical feeling inside the historic theatre.', 68);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1245, 20, 'Monotonous', 'adj', 'Đơn điệu / Tẻ nhạt', 'Doing repetitive office tasks all day long can feel extremely monotonous and tiring.', 69);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1246, 20, 'Mundane', 'adj', 'Bình thường / Thường nhật / Tẻ nhạt', 'Some contemporary artists find inspiration in mundane daily objects like chairs and bottles.', 70);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1247, 20, 'Passionate', 'adj', 'Đam mê / Nhiệt huyết', 'She is passionate about traditional music and practices playing the piano every evening.', 71);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1248, 20, 'Popular', 'adj', 'Phổ biến / Được ưa chuộng', 'Pop music has become very popular among teenagers in almost every country.', 72);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1249, 20, 'Prominent', 'adj', 'Nổi bật / Xuất chúng', 'The gallery is currently displaying works by several prominent artists from around the world.', 73);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1250, 20, 'Relaxing', 'adj', 'Thư giãn / Mang lại cảm giác thư thái', 'Listening to soft classical music in the evening provides a relaxing way to unwind.', 74);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1251, 20, 'Stimulating', 'adj', 'Kích thích / Thú vị / Hứng khởi', 'Art workshops offer a stimulating environment where children can freely explore new ideas.', 75);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1252, 20, 'Visual', 'adj', 'Thuộc về thị giác / Trực quan', 'Teachers often use visual aids like pictures and videos to explain difficult lessons.', 76);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1253, 20, 'Vivid', 'adj', 'Sống động / Rực rỡ', 'The painter used vivid colours to bring the busy street market scene to life.', 77);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1254, 20, 'Choreograph', 'v', 'Biên đạo múa', 'She was invited to choreograph a modern dance routine for the annual cultural festival.', 78);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1255, 20, 'Create', 'v', 'Tạo ra / Sáng tạo', 'Artists use different materials to create meaningful sculptures that reflect human feelings.', 79);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1256, 20, 'Depict', 'v', 'Miêu tả / Khắc họa', 'The murals in the historic temple depict daily life during the ancient dynasties.', 80);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1257, 20, 'Enrich', 'v', 'Làm phong phú / Làm giàu thêm', 'Reading books and visiting art exhibitions can greatly enrich our knowledge and imagination.', 81);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1258, 20, 'Escape', 'v', 'Thoát khỏi / Trốn tránh', 'Many people listen to music or read novels to escape from daily stress.', 82);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1259, 20, 'Imagine', 'v', 'Tưởng tượng / Hình dung', 'It is hard to imagine modern daily life without smartphones and internet access.', 83);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1260, 20, 'Influence', 'v', 'Ảnh hưởng đến / Tác động đến', 'Celebrities and social media can strongly influence the fashion choices of young people.', 84);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1261, 20, 'Inspire', 'v', 'Truyền cảm hứng', 'Dedicated teachers can inspire students to work hard and reach their full potential.', 85);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1262, 20, 'Participate', 'v', 'Tham gia', 'Students are encouraged to participate actively in extracurricular activities like drama and sports.', 86);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1263, 20, 'Perform', 'v', 'Biểu diễn / Trình diễn', 'The school choir will perform traditional folk songs at the upcoming community festival.', 87);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1264, 20, 'Provoke', 'v', 'Kích thích / Gợi lên / Gây ra', 'The thought-provoking painting was intended to provoke deep public debate about environmental pollution.', 88);
INSERT OR IGNORE INTO words (id, topic_id, word, type, meaning, example, order_index) VALUES (1265, 20, 'Transcend', 'v', 'Vượt qua (giới hạn)', 'Great works of art can transcend cultural boundaries and bring diverse communities together.', 89);

